"deepseek-harness\",\n    \"dsh-plugin\",\n    \"dsh-bundle\",\n    \"workbuddy\",\n    \"codebuddy\",\n    \"llm-provider\",\n    \"openai-compatible\",\n    \"local-bridge\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Ianzhyh/workbuddy-to-dsh.git\"\n  },\n  \"homepage\": \"https://github.com/Ianzhyh/workbuddy-to-dsh#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Ianzhyh/workbuddy-to-dsh/issues\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^10.0.1\",\n    \"@types/node\": \"^26.6.4\",\n    \"eslint\": \"^10.12.0\",\n    \"globals\": \"^17.13.0\",\n    \"typescript\": \"^7.0.2\"\n  }\n}\n"
