    {
      "path": "dsh-plugin/lib/bridge.mjs",
      "content": "/**\n * 桥的生命周期与 HTTP 客户端 —— 插件宿主端的底座。\n *\n * 设计约束（与项目 README 的「保留独立桥进程」一致）：\n *   1. 桥仍是**独立进程**，插件只负责「复用已在跑的 / 没跑就拉起 / 需要时停掉」。\n *   2. 因此控制台、`bridge\\start-bridge.cmd`、其它 OpenAI 客户端都不受影响：\n *      它们看到的是同一个 127.0.0.1:8790。\n *   3. 桥的 stdout/stderr 重定向到 `bridge/bridge.log`，与控制台的日志面板同源。\n *\n * 本模块不 import 任何 dsh API，可被单元测试独立驱动。\n */\nimport { spawn } from 'node:child_process';\nimport { createHash } from 'node:crypto';\nimport { existsSync, mkdirSync, openSync, closeSync, readSync, readFileSync, statSync } from 'node:fs';\nimport { dirname, join } from 'node:path';\nimport { LOG_MAX_BYTES as BRIDGE_LOG_MAX_BYTES, rotateLogIfNeeded } from '../vendor/lib/log-rotate.mjs';\n\n/** 默认的桥脚本相对项目根的位置。 */\nexport const BRIDGE_SCRIPT_REL = join('bridge', 'workbuddy-bridge.mjs');\n\n/**\n * 桥源码的内容指纹（与桥 `/health.build` 同一算法）。\n *\n * 升级只换磁盘脚本，不会杀已经在跑的后台桥进程。没有这道比对，用户升级后\n * 会继续被**旧代码**服务：目录/思考档位/换号跟随全是旧的，而版本号看起来\n * 已经是最新（issue #5 的六档位、issue #6 的换号失效都是这个形态）。\n */\nexport function bridgeBuildHash(path) {\n  try {\n    return createHash('sha256').update(readFileSync(path)).digest('hex').slice(0, 16);\n  } catch {\n    return '';\n  }\n}\n\n/*\n * 桥日志滚动上限与控制台同一口径，实现集中在 vendor/lib/log-rotate.mjs。\n * 这里保留具名导出，调用点与 log-rotation.test.mjs 不需要改。\n */\nexport { BRIDGE_LOG_MAX_BYTES, rotateLogIfNeeded };\n/** 默认的桥日志相对项目根的位置（与控制台共用）。 */\nexport const BRIDGE_LOG_REL = join('bridge', 'bridge.log');\n\nconst sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\n/** 拼鉴权头。桥侧 LOCAL_TOKEN 为空时不发头（等价于关闭本地令牌）。 */\nexport function authHeaders(token) {\n  return token ? { authorization: `Bearer ${token}` } : {};\n}\n\n/**\n * 一个桥进程的 HTTP 客户端。\n *\n * 所有方法都显式接收 `signal`，并保证超时——控制台曾经的坑是「/health 等上游\n * 导致 4 秒探测超时被误判为桥未运行」，这里的默认超时同样取短值。\n */\nexport class BridgeClient {\n  /**\n   * @param {{ baseUrl: string, token?: string, timeoutMs?: number }} options\n   */\n  constructor({ baseUrl, token = '', timeoutMs = 8000 }) {\n    this.baseUrl = baseUrl.replace(/\\/+$/, '');\n    this.token = token;\n    this.timeoutMs = timeoutMs;\n  }\n\n  get url() {\n    return this.baseUrl;\n  }\n\n  async #fetch(pathname, { method = 'GET', body, signal, timeoutMs } = {}) {\n    const ac = new AbortController();\n    // 显式传 0 表示「不设超时」（chat 的流式响应不能有整体超时），\n    // 注意不能用 `??`：0 是合法值，会被 ?? 保留下来变成「立刻超时」。\n    const budget = timeoutMs ?? this.timeoutMs;\n    /*\n     * ⚠️ 超时与调用方取消**必须活到响应体读完为止**，不能在拿到响应头时就摘掉。\n     *\n     * `fetch()` 一旦 resolve，AbortSignal 依然控制着**响应体流**的读取 —— 取消\n     * 一个正在流式返回的请求，靠的正是这个 signal。原先 `finally` 在 fetch 解决\n     * 的瞬间就 `removeEventListener` 并清掉定时器，于是：\n     *\n     *   - 调用方 abort（dsh 里点「停止」/ 上层取消）**再也传不进那个流**；\n     *   - 本机继续把上游整段回答读完，只为了把结果丢掉 —— 白烧额度与并发。\n     *\n     * 实测（假上游 100 帧 × 60ms，400ms 处 abort）：\n     *   现状        → read 循环 5 秒仍未结束，abort 后上游又写了 93 帧，且跑完了整条流\n     *   保留监听    → read 2ms 结束，上游残余 0 帧，socket 5ms 内关闭\n     *\n     * 真实链路实测（真实桥 + 真实上游，1.5s 处 abort）：abort 后生成器**又跑了\n     * 9477ms**、期间仍收到 4447 字，最后以 `max-tokens` 收尾（把「用户取消」\n     * 报成了「输出超限」）。\n     *\n     * 所以清理动作挂到**响应体结束**（正常读完 / 被取消 / 出错）上，而不是挂在\n     * 「拿到响应头」上。用一个把 `pull`/`cancel` 都接住的 `ReadableStream` 包一层，\n     * 三种出口都能清理，且背压语义不变。\n     */\n    const cleanup = [];\n    const runCleanup = () => { while (cleanup.length) { try { cleanup.pop()(); } catch { /* 忽略 */ } } };\n    const onAbort = () => ac.abort(signal?.reason);\n    if (signal) {\n      signal.addEventListener('abort', onAbort, { once: true });\n      cleanup.push(() => signal.removeEventListener('abort', onAbort));\n      // 进来时就已经取消：让 fetch 走正常的 abort 失败路径，不静默改成别的语义\n      if (signal.aborted) ac.abort(signal.reason);\n    }\n    if (budget > 0) {\n      const timer = setTimeout(() => ac.abort(new Error('timeout')), budget);\n      cleanup.push(() => clearTimeout(timer));\n    }\n\n    let res;\n    try {\n      res = await fetch(`${this.baseUrl}${pathname}`, {\n        method,\n        headers: {\n          ...authHeaders(this.token),\n          ...(body === undefined ? {} : { 'content-type': 'application/json' }),\n        },\n        body: body === undefined ? undefined : JSON.stringify(body),\n        signal: ac.signal,\n      });\n    } catch (error) {\n      runCleanup(); // 连响应头都没拿到：立刻释放监听与定时器\n      throw error;\n    }\n\n    // 204/205/304 按规范必须无体，`new Response(stream)` 会直接抛；无体响应没有\n    // 「读完」这个时机，当场清理即可。\n    if (!res.body || res.status === 204 || res.status === 205 || res.status === 304) {\n      runCleanup();\n      return res;\n    }\n\n    /*\n     * 重新包一个 Response，让 `.body` / `.text()` / `.json()` 全部走被追踪的流。\n     * 只改 `res.body` 不行：`.text()` 读的是 Response 内部的原始流，包装会失效。\n     *\n     * 三种出口都要清理，缺一个就会漏掉监听或定时器：\n     *   ① 读完（done）—— 正常路径；\n     *   ② 读出错 —— 上游被掐断 / 调用方 abort / 超时；\n     *   ③ cancel —— 消费方主动放弃（例如 adapter 提前退出循环后 reader.cancel()）。\n     * 只用 `pipeThrough(new TransformStream({flush,cancel}))` 会漏掉 ②：\n     * 源流 error 时 flush 不触发，abort 监听与超时定时器就留在那里了。\n     */\n    const reader = res.body.getReader();\n    try {\n      const tracked = new ReadableStream({\n        async pull(controller) {\n          try {\n            const { done, value } = await reader.read();\n            if (done) { runCleanup(); controller.close(); return; }\n            controller.enqueue(value);\n          } catch (error) {\n            runCleanup();\n            controller.error(error);\n          }\n        },\n        cancel(reason) {\n          runCleanup();\n          return reader.cancel(reason).catch(() => {});\n        },\n      });\n      return new Response(tracked, {\n        status: res.status,\n        statusText: res.statusText,\n        headers: res.headers,\n      });\n    } catch (error) {\n      // 构造 Response 失败（响应状态不合规范等）：源流与监听一并收掉，别泄漏\n      runCleanup();\n      await reader.cancel(error).catch(() => {});\n      throw error;\n    }\n  }\n\n  async #json(pathname, options) {\n    const res = await this.#fetch(pathname, options);\n    const text = await res.text();\n    let parsed;\n    try { parsed = JSON.parse(text); } catch { parsed = undefined; }\n    if (!res.ok) {\n      const message = parsed?.error?.message || parsed?.msg || parsed?.message || text || `HTTP ${res.status}`;\n      const error = new Error(String(message).slice(0, 400));\n      error.status = res.status;\n      error.payload = parsed;\n      // 429 的 Retry-After 在头里，不解析出来工具只能干说“稍后”。\n      const retryAfter = Number(res.headers.get('retry-after'));\n      if (Number.isFinite(retryAfter) && retryAfter > 0) error.retryAfter = retryAfter;\n      throw error;\n    }\n    return parsed;\n  }\n\n  /** `GET /health`。桥未运行时抛错（调用方用 {@link probe} 判活在）。 */\n  health(signal) {\n    return this.#json('/health', { signal, timeoutMs: 4000 });\n  }\n\n  /** `GET /v1/identity`：极轻的「现在是谁」，用于账号切换即时刷新（不抓目录）。 */\n  accountIdentity(signal) {\n    return this.#json('/v1/identity', { signal, timeoutMs: 4000 });\n  }\n\n  /** `GET /`：仅用于确认端口上跑的确实是 workbuddy-bridge。 */\n  identity(signal) {\n    return this.#json('/', { signal, timeoutMs: 4000 });\n  }\n\n  /**\n   * `GET /v1/models`。\n   * @param {{ all?: boolean, refresh?: boolean, signal?: AbortSignal }} [options]\n   */\n  models({ all = true, refresh = false, signal } = {}) {\n    const qs = new URLSearchParams();\n    if (all) qs.set('all', '1');\n    if (refresh) qs.set('refresh', '1');\n    const suffix = qs.toString() ? `?${qs}` : '';\n    return this.#json(`/v1/models${suffix}`, { signal, timeoutMs: refresh ? 60000 : 15000 });\n  }\n\n  usage({ days = 7, hours = false, signal } = {}) {\n    return this.#json(`/v1/usage?days=${days}${hours ? '&hours=1' : ''}`, { signal });\n  }\n\n  clearUsage(signal) {\n    return this.#json('/v1/usage', { method: 'DELETE', signal });\n  }\n\n  requests({ limit = 50, signal } = {}) {\n    return this.#json(`/v1/requests?limit=${limit}`, { signal });\n  }\n\n  quota(signal) {\n    return this.#json('/v1/quota', { signal, timeoutMs: 20000 });\n  }\n\n  checkin({ claim = false, signal } = {}) {\n    return this.#json('/v1/checkin', { method: claim ? 'POST' : 'GET', signal, timeoutMs: 20000 });\n  }\n\n  /** 本机所有已登录账号的签到状态（只读；桥侧逐个查上游，慢一点但不多）。 */\n  checkinAccounts({ signal } = {}) {\n    return this.#json('/v1/checkin/accounts', { signal, timeoutMs: 60000 });\n  }\n\n  /** 多账号一次性领取（逐个串行，四个账号约十几秒 —— 超时给足）。 */\n  checkinAll({ signal } = {}) {\n    return this.#json('/v1/checkin/all', { method: 'POST', signal, timeoutMs: 120000 });\n  }\n\n  /**\n   * `POST /v1/web_search`：WorkBuddy 原生网页搜索（不走 DeepSeek）。\n   *\n   * @param {{ query: string, maxResults?: number, allowedDomains?: string[], freshness?: string, signal?: AbortSignal }} options\n   */\n  webSearch({ query, maxResults = 5, allowedDomains, freshness, signal } = {}) {\n    const body = { query, max_results: maxResults };\n    if (Array.isArray(allowedDomains) && allowedDomains.length) body.allowed_domains = allowedDomains;\n    if (freshness) body.freshness = freshness;\n    return this.#json('/v1/web_search', {\n      method: 'POST',\n      body,\n      signal,\n      // 搜索上游本身是模型侧检索，20s 内没回基本就是网关卡住；给足但不无限等。\n      timeoutMs: 45_000,\n    });\n  }\n\n  /**\n   * `POST /v1/videos`：提交 Miora 视频任务（异步，成功即计费）。\n   *\n   * 超时只覆盖“提交并拿到任务 id”这一段；生成本身不在这里等。\n   */\n  videoSubmit({ prompt, mode, firstFrame, lastFrame, references, duration, resolution, aspectRatio, signal } = {}) {\n    const body = {};\n    if (typeof prompt === 'string' && prompt.trim()) body.prompt = prompt.trim();\n    if (mode) body.mode = mode;\n    if (firstFrame) body.first_frame = firstFrame;\n    if (lastFrame) body.last_frame = lastFrame;\n    if (Array.isArray(references) && references.length) body.references = references;\n    if (duration !== undefined) body.duration = duration;\n    if (resolution) body.resolution = resolution;\n    if (aspectRatio) body.aspect_ratio = aspectRatio;\n    return this.#json('/v1/videos', {\n      method: 'POST',\n      body,\n      signal,\n      // 桥侧提交超时 390s（与官方客户端一致）；工具侧略长，避免客户端先放弃。\n      timeoutMs: 400_000,\n    });\n  }\n\n  /** `GET /v1/videos/{id}`：查询任务状态；completed 时带 `output.url(s)`。\n   *\n   * `waitMs > 0` 让桥代客户端轮询（桥侧上限 60 秒），工具不必自己 sleep。\n   */\n  videoStatus(id, { waitMs = 0, signal } = {}) {\n    return this.#mediaStatus('/v1/videos', id, { waitMs, signal });\n  }\n\n  /**\n   * `POST /v1/images`（文生图）或 `/v1/images/edits`（图生图，带 images 时）。\n   * 与视频一样是异步任务：成功返回任务 id，之后用 imageStatus 查询。\n   */\n  imageSubmit({ prompt, images, size, quality, mode, signal } = {}) {\n    const body = {};\n    if (typeof prompt === 'string' && prompt.trim()) body.prompt = prompt.trim();\n    if (mode) body.mode = mode;\n    if (Array.isArray(images) && images.length) body.images = images;\n    if (size) body.size = size;\n    if (quality) body.quality = quality;\n    const path = mode === 'edit' ? '/v1/images/edits' : '/v1/images';\n    return this.#json(path, {\n      method: 'POST',\n      body,\n      signal,\n      // 与视频一致：桥侧提交超时 390s，客户端略长。\n      timeoutMs: 400_000,\n    });\n  }\n\n  /** `GET /v1/images/{id}`：查询图片任务；completed 时带 `output.url(s)`。 */\n  imageStatus(id, { waitMs = 0, signal } = {}) {\n    return this.#mediaStatus('/v1/images', id, { waitMs, signal });\n  }\n\n  /** 视频 / 图片共用的查询：`wait` 秒数夹在 0–60，客户端超时必须比桥晚放弃。 */\n  #mediaStatus(basePath, id, { waitMs = 0, signal } = {}) {\n    const waitSeconds = Math.min(Math.max(Math.ceil(waitMs / 1000), 0), 60);\n    const suffix = waitSeconds > 0 ? `?wait=${waitSeconds}` : '';\n    return this.#json(`${basePath}/${encodeURIComponent(id)}${suffix}`, {\n      signal,\n      timeoutMs: waitSeconds > 0 ? 95_000 : 45_000,\n    });\n  }\n\n  // ── 插件登录（第二条凭据来源）─────────────────────────────────────────\n  /** 凭据来源状态（桌面端/插件、存储模式、生效来源）—— 不含任何令牌。 */\n  authSource(signal) {\n    return this.#json('/v1/auth/source', { signal, timeoutMs: 8000 });\n  }\n\n  /** 插件凭据清单 —— 不含任何令牌。 */\n  authCredentials(signal) {\n    return this.#json('/v1/auth/credentials', { signal, timeoutMs: 8000 });\n  }\n\n  deviceLoginStart({ region = 'cn', open = false } = {}, signal) {\n    return this.#json('/v1/auth/device', { method: 'POST', body: { region, open: open === true }, signal, timeoutMs: 30000 });\n  }\n\n  deviceLoginPoll(state, signal) {\n    return this.#json(`/v1/auth/device?state=${encodeURIComponent(state)}`, { signal, timeoutMs: 30000 });\n  }\n\n  deviceLoginCancel(state, signal) {\n    return this.#json(`/v1/auth/device?state=${encodeURIComponent(state)}`, { method: 'DELETE', signal, timeoutMs: 8000 });\n  }\n\n  authSetActive(uid, signal) {\n    return this.#json('/v1/auth/active', { method: 'POST', body: { uid }, signal, timeoutMs: 8000 });\n  }\n\n  authLogout(uid, signal) {\n    return this.#json(`/v1/auth/credentials?uid=${encodeURIComponent(uid)}`, { method: 'DELETE', signal, timeoutMs: 15000 });\n  }\n\n  setAuthSource(source, signal) {\n    return this.#json('/v1/auth/source', { method: 'POST', body: { source }, signal, timeoutMs: 8000 });\n  }\n\n  /** `POST /v1/chat/completions`，返回原始 Response（SSE 或 JSON）。 */\n  chat(payload, { signal } = {}) {\n    return this.#fetch('/v1/chat/completions', { method: 'POST', body: payload, signal, timeoutMs: 0 });\n  }\n}\n\n/**\n * 桥进程管理器。\n *\n * 状态机很朴素，因为桥本身就是「无状态 + 幂等」的：\n *   probe() → 活 / 不活 / 令牌不匹配 / 端口被别的服务占用\n *   ensure() → 活就复用，不活就拉起并等就绪\n *   stop()   → 只停自己认识的那个 pid（/health 报出来的）\n */\nexport class BridgeSupervisor {\n  /**\n   * @param {object} options\n   * @param {string} options.projectRoot 项目根目录（桥脚本与日志都相对它解析）\n   * @param {string} [options.scriptPath] 桥脚本绝对路径\n   * @param {string} [options.logPath] 桥日志绝对路径\n   * @param {string} options.host\n   * @param {number} options.port\n   * @param {string} options.token\n   * @param {boolean} options.autoStart 探测不活时是否自动拉起\n   * @param {string} [options.nodePath] 启动桥用的 node（默认 process.execPath）\n   * @param {Record<string,string|undefined>} [options.env] 追加/覆盖的环境变量\n   * @param {(line: string) => void} [options.onLog]\n   */\n  constructor(options) {\n    this.projectRoot = options.projectRoot;\n    this.scriptPath = options.scriptPath || join(options.projectRoot, BRIDGE_SCRIPT_REL);\n    this.logPath = options.logPath || join(options.projectRoot, BRIDGE_LOG_REL);\n    this.host = options.host;\n    this.port = options.port;\n    this.token = options.token;\n    /** 登录文件：来自 .env / 配置；多账号时必须显式指定，否则桥会自己探测。 */\n    this.authFile = options.authFile || '';\n    /**\n     * 自动跟随桌面换号：`followAuthFile` 通常是 `'auto'`（由桥解析默认登录文件），\n     * `followUid` 是钉住那一刻该文件里的账号。与控制台拉起桥时注入了同一组\n     * 变量，两套启动路径的行为才不会漂移（issue #6）。\n     */\n    this.followAuthFile = options.followAuthFile || '';\n    this.followUid = options.followUid || '';\n    /** 自动签到开关（undefined = 用桥自己的默认值）。 */\n    this.autoCheckin = options.autoCheckin;\n    this.autoStart = options.autoStart;\n    this.nodePath = options.nodePath || process.execPath;\n    this.env = options.env || {};\n    this.onLog = options.onLog || (() => {});\n\n    this.client = new BridgeClient({\n      baseUrl: `http://${this.host}:${this.port}`,\n      token: this.token,\n      timeoutMs: options.timeoutMs || 8000,\n    });\n    /** 本进程亲手拉起的桥 pid；用于「停止」与「重启」的归属判断。 */\n    this.spawnedPid = null;\n    this.lastStartError = null;\n    this.lastStartAt = null;\n    /** 正在进行的 ensure()，避免并发重复拉起。 */\n    this.pendingEnsure = null;\n  }\n\n  get baseUrl() {\n    return this.client.url;\n  }\n\n  /**\n   * 当前磁盘上桥脚本的指纹（带 stat 缓存：桥脚本几乎不变，不能每次 probe 都读 500KB）。\n   * 文件不存在或读不出时返回空串 —— 此时**不做**构建比对，避免测试/未安装环境误重启。\n   */\n  expectedBuild() {\n    try {\n      const st = statSync(this.scriptPath);\n      const cache = this.buildCache || (this.buildCache = { at: 0, mtimeMs: -1, size: -1, hash: '' });\n      if (cache.mtimeMs === st.mtimeMs && cache.size === st.size) return cache.hash;\n      const hash = bridgeBuildHash(this.scriptPath);\n      Object.assign(cache, { mtimeMs: st.mtimeMs, size: st.size, hash });\n      return hash;\n    } catch {\n      return '';\n    }\n  }\n\n  /**\n   * 端口上的桥与当前脚本是否同一构建。\n   *\n   * 旧桥没有 `/health.build` → 视为不一致（必须重启一次才能把新逻辑装进去）。\n   * 本地脚本读不出（测试桩 / 脚本丢了）→ 无法判断，不触发重启。\n   */\n  buildDiff(health) {\n    const expected = this.expectedBuild();\n    if (!expected) return { expected: '', actual: String(health?.build || ''), stale: false };\n    const actual = String(health?.build || '');\n    return { expected, actual, stale: actual !== expected };\n  }\n\n  /**\n   * 探测桥状态。**不抛错**——把失败翻译成状态。\n   * @returns {Promise<{state: 'running'|'stopped'|'unauthenticated'|'degraded'|'unauthorized'|'foreign', health?: object, error?: string}>}\n   */\n  async probe(signal) {\n    try {\n      const health = await this.client.health(signal);\n      if (!health || health.ok !== true || typeof health.pid !== 'number') {\n        return { state: 'foreign', error: '端口上有一个 HTTP 服务，但它不是 workbuddy-bridge' };\n      }\n      const diff = this.buildDiff(health);\n      return {\n        state: 'running',\n        health,\n        bridgeBuild: diff.actual,\n        expectedBuild: diff.expected,\n        staleBuild: diff.stale,\n      };\n    } catch (error) {\n      /*\n       * 调用方主动取消不是\"桥没运行\"：把 AbortError 映射成 stopped 会让 stop()\n       * 在 SIGTERM 后第一次探测就误报\"已停止\"，ensure() 也可能因此跳过 stop\n       * 直接复用旧进程。单独给一个状态，让调用方如实中止。\n       */\n      if (signal?.aborted) return { state: 'aborted', error: 'probe aborted by caller' };\n      if (error?.status === 401) {\n        /*\n         * 令牌不一致。最常见的原因是**升级**：插件与桥现在共用\n         * `dsh-plugin/.bridge-token`，正常情况下自动一致；但如果用户曾手改\n         * `.env` 里的 `WORKBUDDY_LOCAL_TOKEN`，或旧版本残留了不同的值，就会撞上。\n         * 指到文件位置，让用户能自己核对 —— 只说\"不一致\"等于让人干瞪眼。\n         */\n        return {\n          state: 'unauthorized',\n          error: '端口上已有桥，但本地令牌与本插件配置不一致。'\n            + '检查 .env 的 WORKBUDDY_LOCAL_TOKEN 是否与 dsh-plugin/.bridge-token 相同，'\n            + '或删掉 .env 里那一行让它自动生成；改完重启桥。',\n        };\n      }\n      /**\n       * **桥活着但登录凭据读不出来**：`/health` 会回 503（body 里带 authFile 与原因）。\n       * 这是最常见的真实故障（WorkBuddy 登录过期、登录文件被换掉），必须与\n       * \"端口上是别人的服务\"区分开 —— 否则面板会让人去找一个不存在的端口冲突，\n       * 而且 ensure() 会拒绝复用这个桥。凭 body 形状认领它。\n       */\n      const payload = error?.payload;\n      const looksLikeOurBridge = payload && typeof payload === 'object'\n        && payload.ok === false\n        && (payload.authFile !== undefined || /login|sign in|credential|凭据|登录|token/i.test(String(payload.error || '')));\n      if (looksLikeOurBridge) {\n        /*\n         * 「从来没登录过」与「登录坏了」要分开：前者是首次安装的正常状态，\n         * 面板应该显示「未登录 + 去登录」，而不是吓人的红色「凭据异常」。\n         * 桥的 503 body 带 credential 段，据此区分。\n         */\n        const cred = payload.credential;\n        const noCredential = Boolean(cred)\n          && cred.desktop?.available !== true\n          && Number(cred.plugin?.count || 0) === 0;\n        return {\n          state: noCredential ? 'unauthenticated' : 'degraded',\n          error: String(payload.error || error.message),\n          authFile: payload.authFile,\n          health: payload,\n        };\n      }\n      if (error?.status) {\n        return { state: 'foreign', error: `端口返回 HTTP ${error.status}，不是 workbuddy-bridge` };\n      }\n      return { state: 'stopped', error: String(error?.message || error) };\n    }\n  }\n\n  /** 桥是否活着（不自动拉起）。 */\n  async isRunning(signal) {\n    return (await this.probe(signal)).state === 'running';\n  }\n\n  /**\n   * 保证桥可用：活着就复用，否则按配置拉起并等待就绪。\n   * @param {{ restart?: boolean, signal?: AbortSignal, readyTimeoutMs?: number }} [options]\n   * @returns {Promise<{ok: boolean, started: boolean, reused: boolean, state: string, health?: object, error?: string}>}\n   */\n  async ensure({ restart = false, signal, readyTimeoutMs = 30000, authFile } = {}) {\n    if (this.pendingEnsure) {\n      /*\n       * 在途的 ensure() 如果没有 restart，它可能只是「复用已有桥」—— 直接\n       * 返回它会让调用方以为「已经按新配置重启了」，实际桥根本没动。\n       * 等它结束后再补一次真正的重启。\n       */\n      if (!restart) return this.pendingEnsure;\n      await this.pendingEnsure.catch(() => {});\n      return this.ensure({ restart: true, signal, readyTimeoutMs, authFile });\n    }\n    this.pendingEnsure = this.#ensure({ restart, signal, readyTimeoutMs, authFile })\n      .finally(() => { this.pendingEnsure = null; });\n    return this.pendingEnsure;\n  }\n\n  async #ensure({ restart, signal, readyTimeoutMs, authFile }) {\n    let status = await this.probe(signal);\n    if (status.state === 'aborted') {\n      return { ok: false, started: false, reused: false, state: 'aborted', error: status.error };\n    }\n    let restartReason = '';\n    if (status.state === 'running' && !restart) {\n      /*\n       * 复用前先核对两件事 —— 任何一件不成立都必须重启，否则用户升级后\n       * 会继续被旧进程服务：\n       *   1. 构建指纹：端口上的是不是当前磁盘脚本（旧桥没有 build 字段）；\n       *   2. 登录文件：端口上的桥是不是按我们想要的账号启动的。\n       */\n      const diff = this.buildDiff(status.health);\n      if (diff.stale) {\n        restartReason = `bridge build changed (${diff.actual || 'unknown'} -> ${diff.expected})`;\n      }\n      const desiredAuth = authFile || this.authFile;\n      if (!restartReason && desiredAuth) {\n        const norm = (p) => String(p || '').replace(/\\\\/g, '/').toLowerCase();\n        const want = norm(desiredAuth);\n        const seen = [norm(status.health?.authFile), norm(status.health?.authFilePinned)];\n        if (!seen.includes(want)) {\n          restartReason = `bridge auth file changed (${desiredAuth})`;\n        }\n      }\n      if (!restartReason) {\n        return { ok: true, started: false, reused: true, state: 'running', health: status.health };\n      }\n      this.onLog(restartReason + '; restarting bridge');\n    }\n    if (status.state === 'unauthorized' || status.state === 'foreign') {\n      // 端口被别人占着：不抢，如实报错（抢端口比报错危险得多）\n      return { ok: false, started: false, reused: false, state: status.state, error: status.error };\n    }\n    if (status.state === 'degraded' || status.state === 'unauthenticated') {\n      // 桥在跑，但登录凭据读不出来 / 还没登录：**复用**它并把原因带上去，\n      // 绝不因为\"健康检查不绿\"就再拉一个（会撞端口，而且用户重新登录后同一个进程就能恢复）。\n      /*\n       * 但升级后必须例外：端口上的进程如果还是旧脚本，用户重新登录后仍是旧\n       * 逻辑。先看构建指纹；旧进程有 pid 才停，停不掉就如实报错。\n       */\n      const diff = this.buildDiff(status.health);\n      if (diff.stale) {\n        this.onLog(`bridge build changed while degraded (${diff.actual || 'unknown'} -> ${diff.expected}); restarting bridge`);\n        const stopped = await this.stop(signal);\n        if (!stopped.ok) {\n          return {\n            ok: false,\n            started: false,\n            reused: true,\n            state: status.state,\n            staleBuild: true,\n            error: `${status.error || 'bridge is not ready'}；旧构建进程无法重启：${stopped.error}`,\n          };\n        }\n        // 旧进程已停：继续走下面的 start()，用当前脚本重新拉起\n      } else {\n        return { ok: false, started: false, reused: true, state: status.state, error: status.error, health: status.health };\n      }\n    }\n    if (status.state === 'running' && (restart || restartReason)) {\n      const stopped = await this.stop(signal);\n      if (!stopped.ok) return { ok: false, started: false, reused: false, state: 'running', error: stopped.error };\n    }\n\n    const start = await this.start({ signal, authFile });\n    if (!start.ok) return { ok: false, started: false, reused: false, state: 'stopped', error: start.error };\n\n    const deadline = Date.now() + readyTimeoutMs;\n    let lastError = start.error || '';\n    while (Date.now() < deadline) {\n      if (signal?.aborted) return { ok: false, started: true, reused: false, state: 'starting', error: 'aborted' };\n      await sleep(250);\n      status = await this.probe(signal);\n      if (status.state === 'aborted') {\n        return { ok: false, started: true, reused: false, state: 'aborted', error: status.error };\n      }\n      if (status.state === 'running') {\n        return { ok: true, started: true, reused: false, state: 'running', health: status.health };\n      }\n      if (status.state === 'unauthorized' || status.state === 'foreign') {\n        return { ok: false, started: true, reused: false, state: status.state, error: status.error };\n      }\n      /*\n       * 桥已经起来了，只是还没有凭据：这是首次安装的正常状态，必须立刻返回，\n       * 不能让首次启动白等 readyTimeoutMs（默认 30 秒）才弹出登录引导。\n       */\n      if (status.state === 'unauthenticated' || status.state === 'degraded') {\n        return { ok: false, started: true, reused: false, state: status.state, error: status.error, health: status.health };\n      }\n      lastError = status.error || lastError;\n    }\n    return {\n      ok: false,\n      started: true,\n      reused: false,\n      state: 'starting',\n      error: `桥已拉起但在 ${Math.round(readyTimeoutMs / 1000)} 秒内没有就绪：${lastError}`,\n    };\n  }\n\n  /**\n   * 拉起桥进程。日志重定向到 bridge.log（append），与控制台同源。\n   * @param {{ signal?: AbortSignal, authFile?: string }} [options]\n   */\n  async start({ authFile } = {}) {\n    if (!existsSync(this.scriptPath)) {\n      return { ok: false, pid: null, error: `找不到桥脚本：${this.scriptPath}（用 projectRoot 配置指向 workbuddy-to-dsh 根目录）` };\n    }\n    const alive = await this.isRunning();\n    if (alive) return { ok: true, pid: null, reused: true };\n\n    let logFd = null;\n    try {\n      mkdirSync(dirname(this.logPath), { recursive: true });\n      // 只在**本次真的要拉起新进程**时滚动：桥还活着时上面已经 return 了。\n      rotateLogIfNeeded(this.logPath);\n      logFd = openSync(this.logPath, 'a');\n    } catch { /* 日志打不开不该阻止桥启动 */ }\n\n    const env = {\n      ...process.env,\n      // 显式确保以 node 模式运行：本插件的宿主是 DSH Desktop（Electron），\n      // nodePath 默认取 process.execPath —— 那是 Electron 二进制，没有这个\n      // 变量会以\"应用模式\"启动（弹一个 DSH 窗口而不是跑桥脚本）。手动用\n      // 真 node 跑插件时该变量无害（node 会忽略它）。\n      ELECTRON_RUN_AS_NODE: '1',\n      WORKBUDDY_HOST: this.host,\n      WORKBUDDY_PORT: String(this.port),\n      WORKBUDDY_LOCAL_TOKEN: this.token,\n      WORKBUDDY_LOG: '1',\n      ...(authFile || this.authFile ? { WORKBUDDY_AUTH_FILE: authFile || this.authFile } : {}),\n      ...(this.followAuthFile ? { WORKBUDDY_AUTH_FILE_FOLLOW: this.followAuthFile } : {}),\n      ...(this.followUid ? { WORKBUDDY_AUTH_FOLLOW_UID: this.followUid } : {}),\n      ...(this.autoCheckin === undefined ? {} : { WORKBUDDY_AUTO_CHECKIN: this.autoCheckin ? '1' : '0' }),\n      ...this.env,\n    };\n\n    try {\n      const child = spawn(this.nodePath, [this.scriptPath], {\n        cwd: this.projectRoot,\n        env,\n        // detached：桥要活过 dsh 的重启，这与项目原有的「关掉控制台桥继续驻留」一致\n        detached: true,\n        stdio: logFd === null ? 'ignore' : ['ignore', logFd, logFd],\n        windowsHide: true,\n      });\n      child.unref();\n      this.spawnedPid = child.pid ?? null;\n      this.lastStartAt = Date.now();\n      this.lastStartError = null;\n      this.onLog(`bridge spawned pid=${child.pid} ${this.baseUrl}`);\n      child.on('error', (error) => {\n        this.lastStartError = String(error?.message || error);\n        this.onLog(`bridge spawn error: ${this.lastStartError}`);\n      });\n      return { ok: true, pid: child.pid ?? null, reused: false };\n    } catch (error) {\n      this.lastStartError = String(error?.message || error);\n      return { ok: false, pid: null, error: this.lastStartError };\n    } finally {\n      if (logFd !== null) { try { closeSync(logFd); } catch { /* 忽略 */ } }\n    }\n  }\n\n  /** 停掉桥：只停 /health 报出的那个 pid（本机回环，不会误伤别的服务）。 */\n  async stop(signal) {\n    const status = await this.probe(signal);\n    if (status.state === 'aborted') return { ok: false, stopped: false, error: status.error };\n    if (status.state === 'stopped') return { ok: true, stopped: false, reason: 'bridge was not running' };\n    /*\n     * 未登录 / 凭据异常时桥仍然是我们的进程：503 body 现在带 pid，可以正常停止。\n     * 只有 foreign / unauthorized（没有可信 pid）才拒绝。\n     */\n    const pid = status.health?.pid;\n    if (!['running', 'degraded', 'unauthenticated'].includes(status.state) || !Number.isFinite(pid)) {\n      return { ok: false, error: status.error || status.state };\n    }\n    try {\n      process.kill(pid, 'SIGTERM');\n    } catch (error) {\n      return { ok: false, error: `无法结束 pid ${pid}：${error.message}` };\n    }\n    const deadline = Date.now() + 8000;\n    while (Date.now() < deadline) {\n      await sleep(200);\n      if (signal?.aborted) return { ok: false, stopped: false, error: 'stop aborted by caller' };\n      const nowState = (await this.probe(signal)).state;\n      if (nowState === 'aborted') return { ok: false, stopped: false, error: 'stop aborted by caller' };\n      if (nowState === 'stopped') {\n        if (this.spawnedPid === pid) this.spawnedPid = null;\n        return { ok: true, stopped: true, pid };\n      }\n    }\n    return { ok: false, error: `pid ${pid} 在 8 秒内没有退出` };\n  }\n\n  /**\n   * 读取桥日志尾部（控制台「桥日志」面板读的是同一个文件）。\n   * @param {{ lines?: number, maxBytes?: number }} [options]\n   */\n  readLog({ lines = 200, maxBytes = 512 * 1024 } = {}) {\n    let fd = null;\n    try {\n      if (!existsSync(this.logPath)) return { path: this.logPath, lines: [], size: 0, mtime: null };\n      const stat = statSync(this.logPath);\n      // 只读尾部：bridge.log 是**无限增长**的（追加写），而设置页每 5 秒轮询一次。\n      // 早先的实现先 readFileSync 整个文件再切片 —— 日志涨到几十 MB 后就是每次\n      // 轮询都全量读一遍。这里用 fd 定位到 size - maxBytes 处读。\n      const start = Math.max(0, stat.size - maxBytes);\n      const length = stat.size - start;\n      let text = '';\n      if (length > 0) {\n        fd = openSync(this.logPath, 'r');\n        const buffer = Buffer.alloc(length);\n        const read = readSync(fd, buffer, 0, length, start);\n        text = buffer.subarray(0, read).toString('utf8');\n        // 从中间开始时首行多半是被截断的半行，丢掉它\n        if (start > 0) {\n          const nl = text.indexOf('\\n');\n          text = nl >= 0 ? text.slice(nl + 1) : '';\n        }\n      }\n      const all = text.split(/\\r?\\n/).filter((l) => l.length > 0);\n      return {\n        path: this.logPath,\n        lines: all.slice(-lines),\n        size: stat.size,\n        mtime: stat.mtime.toISOString(),\n      };\n    } catch (error) {\n      return { path: this.logPath, lines: [], size: 0, mtime: null, error: String(error?.message || error) };\n    } finally {\n      if (fd !== null) { try { closeSync(fd); } catch { /* 忽略 */ } }\n    }\n  }\n}\n"
    },
    {
      "path": "dsh-plugin/lib/routes.mjs",
      "content": "/**\n * 面板的 HTTP 数据面 —— 客户端半边（lib/client.js）通过同源 fetch 调它。\n *\n * 为什么走 webServer 路由而不是 RPC/typert：客户端半边只要求「读状态 + 触发\n * 启停」，用普通 HTTP 路由最简单、最好调试，也不必为它维护一套严格反射定义。\n *\n * 安全边界：\n *   - 路由挂在 dsh 自己的 Web 载体上（只监听回环地址）；\n *   - **写操作**额外要求 `x-workbuddy-panel: 1` 头：这会让跨站表单/简单请求\n *     直接打不进来（带自定义头会触发 CORS 预检，而预检不会被放行），\n *     等于用最小代价挡掉 CSRF；读操作只暴露非敏感元数据。\n */\nimport { writeFileSync } from 'node:fs';\n\nimport { cleanLegacyRoutes, detectLegacyRoutes } from './legacy.mjs';\nimport { toDirectory } from './models.mjs';\nimport { createConsoleApiHandler, CONSOLE_API_PREFIX } from './consoleApi.mjs';\n\nconst JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' };\n\nfunction sendJson(res, status, payload) {\n  const body = JSON.stringify(payload);\n  res.writeHead(status, { ...JSON_HEADERS, 'content-length': Buffer.byteLength(body) });\n  res.end(body);\n}\n\nasync function readJsonBody(req, limit = 64 * 1024) {\n  const chunks = [];\n  let size = 0;\n  for await (const chunk of req) {\n    size += chunk.length;\n    if (size > limit) throw new Error('request body too large');\n    chunks.push(chunk);\n  }\n  if (!chunks.length) return {};\n  try { return JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch { return {}; }\n}\n\n/** 校验\"每模型默认参数\"：只收认识且合法的字段，其余丢弃。 */\nfunction sanitizeModelParams(input) {\n  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;\n  const out = {};\n  if (typeof input.temperature === 'number' && Number.isFinite(input.temperature)\n    && input.temperature >= 0 && input.temperature <= 2) out.temperature = input.temperature;\n  if (Number.isInteger(input.maxTokens) && input.maxTokens > 0) out.maxTokens = input.maxTokens;\n  if (typeof input.reasoningEffort === 'string' && input.reasoningEffort.trim()) out.reasoningEffort = input.reasoningEffort.trim();\n  return Object.keys(out).length ? out : null;\n}\n\n/**\n * 上下文预算入参：0 / 空 = 清除覆盖（跟随官方默认），否则要求正整数。\n * 上下文的**上限收敛**仍由 adapter 按模型做（这里不拿目录值拒绝，\n * 否则和“先存意图、目录回来后自然生效”的既有语义冲突）。\n */\nfunction readContextWindow(raw) {\n  if (raw === null || raw === undefined || raw === '' || raw === 0 || raw === '0') return { value: 0 };\n  const n = Number(raw);\n  if (!Number.isSafeInteger(n) || n <= 0 || n > 10_000_000) {\n    return { error: 'contextWindow 需要是正整数（tokens），或 0 表示跟随官方默认' };\n  }\n  return { value: n };\n}\n\n/**\n * @param {object} deps\n * @param {() => object} deps.snapshot 运行态快照\n * @param {() => object} deps.supervisor 桥管理器\n * @param {() => object} deps.consoleSupervisor 控制台管理器\n * @param {() => object} deps.client 桥客户端\n * @param {() => object} deps.adapter\n * @param {object} deps.paths { settingsPath, patchPath }\n * @param {string} deps.provider\n * @param {(line: string, detail?: unknown) => void} deps.log\n */\nexport function createRouteTable(deps) {\n  const {\n    snapshot, supervisor, consoleSupervisor, client, adapter, paths, provider, log,\n    onUpstreamMutation = () => {}, onWritePrefs = () => {}, notifyAdaptersUpdated = () => false,\n    enableWebSearch = async () => { throw new Error('web search configuration is unavailable'); },\n    verifyWebSearch = async () => { throw new Error('web search verification is unavailable'); },\n    revertWebSearch = async () => { throw new Error('web search restore is unavailable'); },\n  } = deps;\n\n  /** 写操作的准入检查。 */\n  const guard = (req) => req.headers['x-workbuddy-panel'] === '1';\n\n  /**\n   * 凭据/账号变了：目录属于旧账号，必须重取，并通知 dsh 的模型选择器。\n   * dsh 不轮询目录，只认 `llm/adapters-updated`；只 invalidate 不通知的话，\n   * 用户登录成功、模型其实已经可用，选择器里却还是旧清单（看起来像没登录）。\n   */\n  const refreshModelCatalog = () => {\n    adapter.invalidate();\n    const task = typeof adapter.warmup === 'function' ? adapter.warmup() : Promise.resolve();\n    Promise.resolve(task).then(\n      () => notifyAdaptersUpdated(),\n      () => notifyAdaptersUpdated(),\n    );\n  };\n\n  /**\n   * 只读路由的方法守门：只允许 GET/HEAD。\n   * 目前非 GET 走进去也只是\"当成读\"（没有副作用），但显式拒绝更严谨 ——\n   * 免得将来有人在某个读分支里加写逻辑，而代理/表单又恰好能打到它。\n   */\n  const readOnly = (req, res) => {\n    if (req.method === 'GET' || req.method === 'HEAD') return false;\n    sendJson(res, 405, { ok: false, error: `${req.method} not allowed on a read-only route` });\n    return true;\n  };\n\n  return [\n    {\n      kind: 'exact',\n      path: '/workbuddy/status',\n      async handler(req, res) {\n        if (readOnly(req, res)) return;\n        try {\n          // ?quota=1：**强制**重读积分（平时 120 秒缓存；面板上的\"刷新\"按钮要立刻看到新值）\n          const url = new URL(req.url, 'http://127.0.0.1');\n          const forceQuota = url.searchParams.get('quota') === '1';\n          sendJson(res, 200, { ok: true, ...(await snapshot({ quota: forceQuota })) });\n        } catch (error) {\n          log('panel status failed', error);\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/identity',\n      async handler(req, res) {\n        if (readOnly(req, res)) return;\n        try {\n          const identity = await client.accountIdentity(AbortSignal.timeout(4000));\n          sendJson(res, 200, { ok: true, ...identity });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/web-search/enable',\n      async handler(req, res) {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: `${req.method} not allowed` });\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const result = await enableWebSearch();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          log('panel web-search configure failed', error);\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      // 只跑自检、不改配置：状态卡上的「重新检测」用它，避免为了看一眼结果\n      // 重新写入 settings/credentials。真实搜索会消耗一次额度，因此仍要求面板头。\n      kind: 'exact',\n      path: '/workbuddy/web-search/verify',\n      async handler(req, res) {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: `${req.method} not allowed` });\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const result = await verifyWebSearch();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          log('panel web-search verify failed', error);\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      // 恢复一键接入前的 dsh 搜索配置。只改 dsh settings/独立凭据引用，\n      // 不碰 WorkBuddy 客户端文件；仍要求面板头，避免跨站触发配置回滚。\n      kind: 'exact',\n      path: '/workbuddy/web-search/revert',\n      async handler(req, res) {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: `${req.method} not allowed` });\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const result = await revertWebSearch();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          log('panel web-search restore failed', error);\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      // 积分专用：GET 读缓存，POST 强制刷新（要面板头，避免跨站触发上游调用）\n      kind: 'exact',\n      path: '/workbuddy/quota',\n      async handler(req, res) {\n        try {\n          if (req.method === 'POST') {\n            if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n            const snap = await snapshot({ quota: true });\n            return sendJson(res, 200, {\n              ok: snap.quota?.ok !== false,\n              quota: snap.quota,\n              quotaError: snap.quotaError,\n              at: snap.quotaAt,\n              refreshed: true,\n              /*\n               * 桥状态随积分一起返回：桥掉登录态时 quota 可能还是上一个账号的\n               * 缓存，光看 `ok/quotaError` 分辨不出来。客户端据此决定要不要\n               * 把胶囊换成登录入口，不必再单独轮询 /workbuddy/status。\n               */\n              bridgeState: snap.bridge?.state || '',\n              bridgeAccount: snap.bridgeAccount || null,\n              quotaAccount: snap.quotaAccount || null,\n            });\n          }\n          if (readOnly(req, res)) return;\n          const snap = await snapshot({});\n          sendJson(res, 200, {\n            ok: snap.quota?.ok !== false,\n            quota: snap.quota,\n            quotaError: snap.quotaError,\n            at: snap.quotaAt,\n            bridgeState: snap.bridge?.state || '',\n            bridgeAccount: snap.bridgeAccount || null,\n            quotaAccount: snap.quotaAccount || null,\n          });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      // 插件登录状态：来源 + 凭据清单。桥是唯一事实来源；这里只做展示。\n      // 响应里**永远不含** access / refresh token（桥侧已经保证，这里也不二次加工）。\n      kind: 'exact',\n      path: '/workbuddy/login',\n      async handler(req, res) {\n        if (readOnly(req, res)) return;\n        try {\n          const [source, creds] = await Promise.all([client.authSource(), client.authCredentials()]);\n          sendJson(res, 200, {\n            ok: true,\n            ...source,\n            configuredSource: creds.configuredSource,\n            credentials: Array.isArray(creds.credentials) ? creds.credentials : [],\n          });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error), credentials: [] });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/login/start',\n      async handler(req, res) {\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          const started = await client.deviceLoginStart({\n            region: body?.region === 'global' ? 'global' : 'cn',\n            open: body?.open === true,\n          });\n          sendJson(res, 200, { ok: true, ...started });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/login/poll',\n      async handler(req, res) {\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          if (!body?.state) return sendJson(res, 400, { ok: false, error: 'state is required' });\n          const result = await client.deviceLoginPoll(String(body.state));\n          if (result?.status === 'ready') {\n            // 账号换了：模型目录与余额/签到缓存都属于上一个账号\n            refreshModelCatalog();\n            onUpstreamMutation();\n          }\n          sendJson(res, 200, result);\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/login/cancel',\n      async handler(req, res) {\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          const result = await client.deviceLoginCancel(String(body?.state || ''));\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/login/active',\n      async handler(req, res) {\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          if (!body?.uid) return sendJson(res, 400, { ok: false, error: 'uid is required' });\n          const result = await client.authSetActive(String(body.uid));\n          refreshModelCatalog();\n          onUpstreamMutation();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/login/logout',\n      async handler(req, res) {\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          if (!body?.uid) return sendJson(res, 400, { ok: false, error: 'uid is required' });\n          const result = await client.authLogout(String(body.uid));\n          refreshModelCatalog();\n          onUpstreamMutation();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/login/source',\n      async handler(req, res) {\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          const result = await client.setAuthSource(String(body?.source || 'auto'));\n          refreshModelCatalog();\n          onUpstreamMutation();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/models',\n      async handler(req, res) {\n        if (readOnly(req, res)) return;\n        try {\n          const url = new URL(req.url, 'http://127.0.0.1');\n          const refresh = url.searchParams.get('refresh') === '1';\n          const catalog = await adapter.catalog({ refresh });\n          // 返回**归一化后**的目录（contextWindow/maxTokens/images/free…），\n          // 不退上游原始字段名（context_window/max_output_tokens）：\n          // 面板与其它消费者只认一种形状，免得两处各说一套。\n          // contextWindow 是实际生效值（该模型的面板预算优先，按模型上限收敛）。\n          sendJson(res, 200, {\n            ok: true,\n            models: toDirectory(catalog, {\n              contextWindows: typeof adapter.contextWindowsSnapshot === 'function'\n                ? adapter.contextWindowsSnapshot()\n                : {},\n            }),\n            at: adapter.catalogCache.at,\n            error: adapter.catalogError || '',\n            // staleMs>0 = 这次强制刷新失败、退回旧缓存：面板要能如实说\"你看到的是旧目录\"\n            refreshed: adapter.lastRefresh?.refresh === true,\n            staleMs: Number(adapter.lastRefresh?.staleMs) || 0,\n          });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, models: [], error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      // 模型显示偏好：GET 读当前生效清单，POST 写并即时生效（无需重启）。\n      // 读：任何 GET 都行（非敏感）；写：要面板头（挡跨站，与其它写路由一致）。\n      // 注意这里**没有**碰 .state.json —— 那份文件是控制台的单写者领地，\n      // 偏好存在插件自己的 .model-prefs.json（见 index.js 里的说明）。\n      kind: 'exact',\n      path: '/workbuddy/model-visibility',\n      async handler(req, res) {\n        try {\n          if (req.method === 'POST') {\n            if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n            const body = await readJsonBody(req);\n            const current = (typeof deps.readPrefs === 'function' ? deps.readPrefs() : null)\n              || { visible: null, hideAll: false, contextWindowByModel: {}, paramsByModel: {} };\n            /*\n             * 面板的「上下文窗口（Token）」表单：输入 + 输出一次提交。\n             *\n             * 必须排在两个单字段分支**前面**：旧实现的单字段分支各自只看一个\n             * 字段，组合请求会落进 params 分支、把 contextWindow 静默吞掉。\n             * 这里一次落盘、一次广播，避免“输入存了、输出没存”的半套状态。\n             */\n            if (typeof body?.model === 'string'\n              && Object.prototype.hasOwnProperty.call(body, 'contextWindow')\n              && Object.prototype.hasOwnProperty.call(body, 'params')) {\n              const model = body.model;\n              const parsed = readContextWindow(body.contextWindow);\n              if (parsed.error) return sendJson(res, 400, { ok: false, error: parsed.error });\n              const cleaned = body.params === null ? null : sanitizeModelParams(body.params);\n              /*\n               * 输入/输出共享窗口只做建议，不在服务端硬拒绝：官方模型本身\n               * 就可能给“默认输入 300K + 输出上限 384K”的组合。是否可用\n               * 以上游实际限制为准，面板会提示但不阻断。\n               */\n              const contextWindowByModel = { ...(current.contextWindowByModel || {}) };\n              if (parsed.value > 0) contextWindowByModel[model] = parsed.value;\n              else delete contextWindowByModel[model];\n              const paramsByModel = { ...(current.paramsByModel || {}) };\n              if (cleaned) paramsByModel[model] = cleaned;\n              else delete paramsByModel[model];\n              // 先落盘再应用：写失败时不要留下“内存里已生效、重启后又变回去”的状态。\n              onWritePrefs({\n                visible: current.visible,\n                hideAll: current.hideAll === true,\n                includeUnofficial: current.includeUnofficial === true,\n                contextWindowByModel,\n                paramsByModel,\n              });\n              if (typeof adapter.setContextWindows === 'function') adapter.setContextWindows(contextWindowByModel);\n              if (typeof adapter.setModelParams === 'function') adapter.setModelParams(paramsByModel);\n              // 预算参与 dsh 的容量解析，参数参与 resolveModel；一次广播让两者都重算。\n              const applied = notifyAdaptersUpdated();\n              return sendJson(res, 200, {\n                ok: true,\n                model,\n                contextWindow: parsed.value,\n                params: paramsByModel[model] || null,\n                contextWindowByModel,\n                paramsByModel,\n                applied,\n              });\n            }\n            /*\n             * 每模型上下文预算：面板详情里每个模型有自己的输入/输出。\n             * 它和\"显示哪些模型\"、每模型默认参数都正交；单字段分支保留给\n             * 旧客户端 / 脚本，新面板走上面的组合分支。\n             * `contextWindow: 0` = 清除该模型的覆盖，回到官方默认/桥目录值。\n             */\n            if (typeof body?.model === 'string'\n              && Object.prototype.hasOwnProperty.call(body, 'contextWindow')\n              && !Object.prototype.hasOwnProperty.call(body, 'params')) {\n              const model = body.model;\n              const parsed = readContextWindow(body.contextWindow);\n              if (parsed.error) return sendJson(res, 400, { ok: false, error: parsed.error });\n              const value = parsed.value;\n              const contextWindowByModel = { ...(current.contextWindowByModel || {}) };\n              if (value > 0) contextWindowByModel[model] = value;\n              else delete contextWindowByModel[model];\n              // 先落盘再应用：写失败时不要留下“内存里已生效、重启后又变回去”的状态。\n              onWritePrefs({\n                visible: current.visible,\n                hideAll: current.hideAll === true,\n                includeUnofficial: current.includeUnofficial === true,\n                contextWindowByModel,\n                paramsByModel: current.paramsByModel || {},\n              });\n              if (typeof adapter.setContextWindows === 'function') adapter.setContextWindows(contextWindowByModel);\n              // 预算只影响元数据，不换目录，但仍要广播：dsh 用它重新解析\n              // 每个模型的容量（token meter 的占用分母）。\n              const applied = notifyAdaptersUpdated();\n              return sendJson(res, 200, { ok: true, model, contextWindow: value, contextWindowByModel, applied });\n            }\n            /*\n             * 每模型默认参数：与\"显示哪些\"分开保存（同一份 prefs 文件的不同字段）。\n             * `params: null` = 清除该模型的默认参数；其余字段做白名单校验。\n             */\n            if (typeof body?.model === 'string' && Object.prototype.hasOwnProperty.call(body, 'params')) {\n              const model = body.model;\n              const paramsByModel = { ...(current.paramsByModel || {}) };\n              const cleaned = body.params === null ? null : sanitizeModelParams(body.params);\n              if (cleaned) paramsByModel[model] = cleaned;\n              else delete paramsByModel[model];\n              // 先落盘再应用：写失败时不要留下“内存里已生效、重启后又变回去”的状态。\n              onWritePrefs({\n                visible: current.visible,\n                hideAll: current.hideAll === true,\n                includeUnofficial: current.includeUnofficial === true,\n                contextWindowByModel: current.contextWindowByModel || {},\n                paramsByModel,\n              });\n              if (typeof adapter.setModelParams === 'function') adapter.setModelParams(paramsByModel);\n              return sendJson(res, 200, {\n                ok: true, model, params: paramsByModel[model] || null, paramsByModel,\n                contextWindowByModel: current.contextWindowByModel || {},\n              });\n            }\n            /*\n             * 「显示官方目录外的模型」：与 visible/hideAll 正交。\n             * 官方列表（official=true）之外的老型号/未开通线路默认不进 dsh\n             * 选择器；打开这个开关后按 visible 的规则一并显示。\n             *\n             * 只有**单独**提交这个开关时才走捷径。面板保存会同时带\n             * `visible`/`unset`/`hideAll` —— 旧实现先命中这里就直接返回，\n             * 把用户的勾选整批丢掉（实测：保存后面板读回空数组）。\n             */\n            const hasVisibilityIntent = Object.prototype.hasOwnProperty.call(body, 'visible')\n              || Object.prototype.hasOwnProperty.call(body, 'unset')\n              || Object.prototype.hasOwnProperty.call(body, 'hideAll');\n            if (typeof body?.includeUnofficial === 'boolean' && !hasVisibilityIntent) {\n              const includeUnofficial = body.includeUnofficial;\n              adapter.setFilter({\n                allow: current.visible === null ? undefined : (current.visible || []),\n                hideAll: current.hideAll === true,\n                includeUnofficial,\n              });\n              onWritePrefs({\n                visible: current.visible,\n                hideAll: current.hideAll === true,\n                includeUnofficial,\n                contextWindowByModel: current.contextWindowByModel || {},\n                paramsByModel: current.paramsByModel || {},\n              });\n              const applied = notifyAdaptersUpdated();\n              return sendJson(res, 200, {\n                ok: true, includeUnofficial,\n                contextWindowByModel: current.contextWindowByModel || {},\n                applied,\n              });\n            }\n            /*\n             * 三种显示意图，必须分开建模（旧实现只认 `visible` 数组）：\n             *   - unset（恢复全部）：回到配置的 allow/deny（每模型参数保留）；\n             *   - hideAll（全不选）：一个都不显示 —— `visible: []` 单独存在时\n             *     不能当成\"没设置\"，否则 dsh 里反而全部还在；\n             *   - 勾选清单：只显示这些。\n             */\n            const wantsUnset = body?.unset === true || body?.visible === null;\n            const includeUnofficial = typeof body?.includeUnofficial === 'boolean'\n              ? body.includeUnofficial\n              : current.includeUnofficial === true;\n            if (wantsUnset) {\n              // 只重置\"哪些模型显示\"，不重置\"是否包含官方目录外\"\n              adapter.resetFilter();\n              adapter.setFilter({ includeUnofficial });\n              onWritePrefs({\n                visible: null,\n                hideAll: false,\n                includeUnofficial,\n                contextWindowByModel: current.contextWindowByModel || {},\n                paramsByModel: current.paramsByModel || {},\n              });\n              const applied = notifyAdaptersUpdated();\n              return sendJson(res, 200, {\n                ok: true, unset: true, visible: null, hideAll: false, includeUnofficial,\n                contextWindowByModel: current.contextWindowByModel || {},\n                count: 0, applied,\n              });\n            }\n            /*\n             * 空/截断的请求体不能落到「visible=[] → hideAll=true」：以前一次\n             * 没带字段的 POST 就会把 dsh 选择器清空（还广播 adapters-updated），\n             * 而接口自己回 200。这里要求明确的显示意图。\n             */\n            if (!hasVisibilityIntent) {\n              return sendJson(res, 400, {\n                ok: false,\n                error: 'visible / unset / hideAll 至少需要一个（空请求不会改动显示偏好）',\n              });\n            }\n            const visible = Array.isArray(body?.visible) ? body.visible.map(String).filter(Boolean) : [];\n            const hideAll = body?.hideAll === true || visible.length === 0;\n            // 目录里不存在的 id 也照存：上游目录可能暂时没抓到，用户勾选的意图优先，\n            // 目录恢复后自然重新生效。\n            adapter.setFilter({ allow: visible, hideAll, includeUnofficial });\n            onWritePrefs({\n              visible,\n              hideAll,\n              includeUnofficial,\n              contextWindowByModel: current.contextWindowByModel || {},\n              paramsByModel: current.paramsByModel || {},\n            });\n            // 广播 llm/adapters-updated：dsh 的模型选择器**不轮询**目录，只认这个\n            // 事件。不广播的话 filter 虽已生效，但 UI 会一直显示旧清单。\n            const applied = notifyAdaptersUpdated();\n            return sendJson(res, 200, {\n              ok: true,\n              unset: false,\n              visible,\n              hideAll,\n              includeUnofficial,\n              contextWindowByModel: current.contextWindowByModel || {},\n              count: hideAll ? 0 : visible.length,\n              applied,\n            });\n          }\n          if (readOnly(req, res)) return;\n          const current2 = typeof deps.readPrefs === 'function' ? deps.readPrefs() : null;\n          const filter = typeof adapter.filterSnapshot === 'function'\n            ? adapter.filterSnapshot()\n            : { allow: [], deny: [], hideAll: false };\n          sendJson(res, 200, {\n            ok: true,\n            // `unset` 与 `visible: []` 是两种状态：前者=跟随配置（全显示），\n            // 后者=用户点过\"全不选\"（全隐藏）。只有每模型参数、没有显示偏好时\n            // visible 也是 null（显示跟随配置）。\n            unset: !current2 || current2.visible === null,\n            visible: current2 ? current2.visible : null,\n            hideAll: current2 ? current2.hideAll === true : false,\n            /** 是否把官方目录外的模型也放进 dsh 选择器 */\n            includeUnofficial: current2 ? current2.includeUnofficial === true : false,\n            /**\n             * 每模型上下文预算（`{ [modelId]: tokens }`；缺条目 = 跟随官方默认）。\n             * 实际生效值按各模型上限收敛，见 /workbuddy/models 的 contextWindow。\n             */\n            contextWindowByModel: typeof adapter.contextWindowsSnapshot === 'function'\n              ? adapter.contextWindowsSnapshot()\n              : (current2?.contextWindowByModel || {}),\n            /** 每模型默认参数（面板详情里编辑） */\n            paramsByModel: typeof adapter.modelParamsSnapshot === 'function'\n              ? adapter.modelParamsSnapshot()\n              : (current2?.paramsByModel || {}),\n            /** 配置里 modelDeny 排除的模型：面板据此标出来，避免\"勾了也不出现\"的疑惑 */\n            deny: filter.deny || [],\n            at: adapter.catalogCache.at,\n          });\n        } catch (error) {\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/usage',\n      async handler(req, res) {\n        try {\n          if (req.method === 'DELETE') {\n            if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n            // 账本由桥维护（内存副本 + 文件），必须让桥自己清 —— 与控制器同一条路径\n            await client.clearUsage();\n            return sendJson(res, 200, { ok: true, cleared: true });\n          }\n          const url = new URL(req.url, 'http://127.0.0.1');\n          const days = Math.min(Math.max(Number(url.searchParams.get('days')) || 7, 1), 90);\n          const hours = url.searchParams.get('hours') === '1';\n          sendJson(res, 200, { ok: true, ...(await client.usage({ days, hours })) });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/requests',\n      async handler(req, res) {\n        if (readOnly(req, res)) return;\n        try {\n          const url = new URL(req.url, 'http://127.0.0.1');\n          const limit = Math.min(Math.max(Number(url.searchParams.get('limit')) || 50, 1), 500);\n          sendJson(res, 200, { ok: true, ...(await client.requests({ limit })) });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/log',\n      async handler(req, res) {\n        try {\n          if (req.method === 'DELETE') {\n            if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n            // 桥持有 bridge.log 的追加 fd：截断后它从新文件末尾继续（O_APPEND），与控制器一致\n            try {\n              writeFileSync(supervisor.logPath, '');\n              return sendJson(res, 200, { ok: true, cleared: true });\n            } catch (error) {\n              return sendJson(res, 500, { ok: false, cleared: false, error: String(error?.message || error) });\n            }\n          }\n          const url = new URL(req.url, 'http://127.0.0.1');\n          const lines = Math.min(Math.max(Number(url.searchParams.get('lines')) || 200, 1), 2000);\n          sendJson(res, 200, { ok: true, ...supervisor.readLog({ lines }) });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/checkin',\n      async handler(req, res) {\n        try {\n          // GET = 读状态；POST?claim=1 = 领取（写，需要面板头）；其它方法拒绝\n          if (req.method !== 'GET' && req.method !== 'HEAD' && req.method !== 'POST') {\n            return sendJson(res, 405, { ok: false, error: `${req.method} not allowed` });\n          }\n          const url = new URL(req.url, 'http://127.0.0.1');\n          const claim = req.method === 'POST' && url.searchParams.get('claim') === '1';\n          if (claim && !guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n          const result = await client.checkin({ claim });\n          // 领取成功 = 上游余额变了：作废插件侧积分/签到缓存（下一次快照重取新值），\n          // 否则面板最长 120 秒还显示领取前的余额\n          if (claim && result?.ok !== false) onUpstreamMutation();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/checkin/accounts',\n      async handler(req, res) {\n        if (req.method !== 'GET' && req.method !== 'HEAD') {\n          return sendJson(res, 405, { ok: false, error: `${req.method} not allowed` });\n        }\n        try {\n          const result = await client.checkinAccounts();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/checkin/all',\n      async handler(req, res) {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'POST only' });\n        // 会往每个账号各发一次领取请求：必须带面板头，避免被同机页面顺手触发\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const result = await client.checkinAll();\n          if (result?.ok !== false) onUpstreamMutation();\n          sendJson(res, 200, { ok: true, ...result });\n        } catch (error) {\n          sendJson(res, 200, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/bridge',\n      async handler(req, res) {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'POST only' });\n        if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n        try {\n          const body = await readJsonBody(req);\n          const action = String(body?.action || 'status');\n          if (action === 'start') {\n            const result = await supervisor.ensure({});\n            refreshModelCatalog();\n            return sendJson(res, 200, { ok: result.ok, action, result });\n          }\n          if (action === 'stop') {\n            const result = await supervisor.stop();\n            adapter.invalidate();\n            return sendJson(res, 200, { ok: result.ok, action, result });\n          }\n          if (action === 'restart') {\n            const result = await supervisor.ensure({ restart: true });\n            refreshModelCatalog();\n            return sendJson(res, 200, { ok: result.ok, action, result });\n          }\n          const probe = await supervisor.probe();\n          return sendJson(res, 200, { ok: true, action: 'status', result: probe });\n        } catch (error) {\n          log('panel bridge action failed', error);\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/console',\n      async handler(req, res) {\n        try {\n          if (req.method !== 'POST') {\n            if (readOnly(req, res)) return;\n            const probe = await consoleSupervisor.probe({ cached: false });\n            return sendJson(res, 200, { ok: true, url: consoleSupervisor.url, state: probe.state, error: probe.error || '', managed: consoleSupervisor.spawnedPid !== null });\n          }\n          if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n          const body = await readJsonBody(req);\n          const action = String(body?.action || 'start');\n          if (action === 'stop') {\n            const result = await consoleSupervisor.stop();\n            return sendJson(res, 200, { ok: result.ok, action, url: consoleSupervisor.url, result });\n          }\n          const result = await consoleSupervisor.ensure({});\n          return sendJson(res, 200, { ok: result.ok, action: 'start', url: consoleSupervisor.url, result });\n        } catch (error) {\n          log('panel console action failed', error);\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/workbuddy/migrate',\n      async handler(req, res) {\n        try {\n          if (req.method === 'POST') {\n            if (!guard(req)) return sendJson(res, 403, { ok: false, error: 'missing x-workbuddy-panel header' });\n            const body = await readJsonBody(req);\n            const dryRun = body?.dryRun === true;\n            const result = cleanLegacyRoutes({ settingsPath: paths.settingsPath, patchPath: paths.patchPath, provider, dryRun });\n            log(`legacy cleanup ${dryRun ? '(dry-run) ' : ''}changed=${result.changed}`);\n            return sendJson(res, 200, { ok: true, ...result });\n          }\n          if (readOnly(req, res)) return;\n          const detected = detectLegacyRoutes({ settingsPath: paths.settingsPath, patchPath: paths.patchPath, provider });\n          sendJson(res, 200, { ok: true, ...detected });\n        } catch (error) {\n          sendJson(res, 500, { ok: false, error: String(error?.message || error) });\n        }\n      },\n    },\n    // 控制台域的功能（账号 / 诊断 / 体检 / 对话测试 / 自动签到开关）原样透传，\n    // 白名单见 consoleApi.mjs —— 单写者，两边状态才不会各说一套。\n    {\n      kind: 'prefix',\n      path: CONSOLE_API_PREFIX,\n      handler: createConsoleApiHandler({\n        consoleSupervisor,\n        log,\n        onUpstreamMutation,\n        onAccountSwitch: refreshModelCatalog,\n      }),\n    },\n  ];\n}\n\n/**\n * 把路由表挂到 dsh 的 Web 载体上。\n * @param {object} target 要么是 webServer 服务本身，要么是一个能 `get('webServer')` 的 ctx\n * @returns {() => void} 幂等 disposer\n */\nexport function mountRoutes(target, routes, log = () => {}) {\n  const webServer = typeof target?.register === 'function' ? target : target?.get?.('webServer');\n  if (!webServer) {\n    log('webServer 服务不可用，面板数据面未挂载（GUI 面板会显示离线）');\n    return () => {};\n  }\n  const disposers = [];\n  for (const route of routes) {\n    try {\n      disposers.push(webServer.register({ kind: route.kind, path: route.path, handler: route.handler }));\n    } catch (error) {\n      log(`挂载路由 ${route.path} 失败`, error);\n    }\n  }\n  log(`已挂载 ${disposers.length}/${routes.length} 条面板路由`);\n  return () => { for (const dispose of disposers.splice(0)) { try { dispose(); } catch { /* 忽略 */ } } };\n}\n"
    },
    {
      "path": "dsh-plugin/lib/tools.mjs",
      "content": "/**\n * 模型可见的工具 —— 让 agent 自己能问「桥怎么样 / 有哪些模型 / 花了多少」。\n *\n * ToolDefinition 契约（dsh tools 服务）：\n *   { name, description, parameters, output: { schema, render(args, value) }, execute(args, exec) }\n * 工具返回值必须是 JsonValue；模型看到的内容由 `output.render` 产出。\n * 这里统一用「返回格式化好的字符串 + render 成文本块」，好读也好测。\n */\nimport { humanDuration } from './models.mjs';\nimport { formatBytes, saveMediaFile } from './media-file.mjs';\n\n/** 把一次调用包装成 TextBlock 数组。 */\nconst asText = (value) => [{ type: 'text', text: typeof value === 'string' ? value : JSON.stringify(value, null, 2) }];\n\n/** 统一构造一个「返回文本报告」的工具。 */\nfunction textTool({ name, description, parameters, execute, timeoutMs }) {\n  return {\n    name,\n    description,\n    parameters,\n    output: { schema: { type: 'string' }, render: (_args, value) => asText(value) },\n    execute,\n    ...(timeoutMs ? { timeoutMs } : {}),\n  };\n}\n\nconst fmtTokens = (n) => (Number(n) >= 1000 ? `${(Number(n) / 1000).toFixed(1)}k` : String(Number(n) || 0));\n\n/**\n * 模型给「图片输入」时可能出现的几种形状。\n *\n * 这是踩过的真实体验问题：工具层原先用\n *   `typeof item === 'string' && item.trim()`\n * 过滤参考图/首帧，非字符串**静默丢弃**。于是模型把首帧写成\n * `{ \"path\": \"C:/x.png\" }` 或 `{ \"url\": \"https://…\" }`（这在多模态协议里很常见）\n * 时，图片被悄悄扔掉 → 模式退化成文生视频 / 文生图 → **照常计费，但图根本没带上**。\n * 桥侧那条「未知字段一律 400」的防线拦不住这种情况，因为到达桥时字段已经是空数组了。\n *\n * 所以工具层现在负责**认形状**：认得出来的就取出字符串（含常见的 `path`/`url`/\n * `file_key`/`base64` 包装），认不出来的直接拒绝调用 —— 宁可让模型重发一次参数，\n * 也不能让它以为图带上了。\n *\n * @param {unknown} value\n * @param {string} field 用于错误文案的字段名\n * @returns {string} 归一化后的图片输入\n */\nfunction imageInputString(value, field) {\n  if (typeof value === 'string') {\n    const text = value.trim();\n    if (!text) throw new Error(`${field} 是空字符串；要么给一个有效的图片来源，要么不要传这个参数。`);\n    return text;\n  }\n  if (value && typeof value === 'object' && !Array.isArray(value)) {\n    for (const key of ['path', 'file', 'url', 'file_key', 'fileKey', 'base64', 'data']) {\n      const inner = value[key];\n      if (typeof inner === 'string' && inner.trim()) {\n        const text = inner.trim();\n        // base64/data 裸串补成 data URI，否则桥会把它当成「相对路径」拒掉。\n        // 但 `data` 这个键也可能是 URL/fileKey（多模态协议里两种写法都见过），\n        // 只有既不像 URI 也不像 fileKey 时才按 base64 处理。\n        const looksLikeRef = /^data:/i.test(text)\n          || /^https?:\\/\\//i.test(text)\n          || /^(?:bga|file)\\//.test(text);\n        if ((key === 'base64' || key === 'data') && !looksLikeRef) {\n          const mime = typeof value.mime_type === 'string'\n            ? value.mime_type\n            : (typeof value.mimeType === 'string' ? value.mimeType : 'image/png');\n          return `data:${mime};base64,${text}`;\n        }\n        return text;\n      }\n    }\n    throw new Error(`${field} 是一个对象，但没有 path/url/file_key/base64/data 字段；`\n      + '请直接传字符串（本地绝对路径 / 公网 https URL / data URI / miora fileKey）。');\n  }\n  if (typeof value === 'number' || typeof value === 'boolean') {\n    throw new Error(`${field} 必须是字符串，收到的是 ${typeof value}。`);\n  }\n  throw new Error(`${field} 的取值无法识别；请传字符串（本地绝对路径 / 公网 https URL / data URI / miora fileKey）。`);\n}\n\n/**\n * 归一化 `images[]`（图生图）。\n *\n * 与 `imageInputString` 同一动机：任何一项认不出来都让整次调用失败，\n * 不留下「看起来成功、其实少带了图」的提交。\n */\nfunction imageInputList(value, field) {\n  if (value === undefined || value === null) return [];\n  const list = Array.isArray(value) ? value : [value];\n  const out = [];\n  for (let index = 0; index < list.length; index += 1) {\n    const item = list[index];\n    if (item === undefined || item === null) continue;\n    if (typeof item === 'string' && !item.trim()) continue; // 空串按「没给」处理（模型常填 \"\"）\n    out.push(imageInputString(item, `${field}[${index}]`));\n  }\n  return out;\n}\n\n/**\n * 产物交付文案（视频 / 图片共用）。\n *\n * 默认只给 URL 并说明它会过期；用户传了 `save_to` 就**当场落盘**，回执给的是\n * 本地绝对路径 —— 那才是用户能双击打开、能拖进剪辑软件的东西。下载失败不抛错，\n * 而是把原因写进文案再退回 URL：产物已经生成、钱已经花了，绝不能因为\n * 「存不下来」就让这次查询看起来失败。\n *\n * @param {{ urls: string[], kind: 'video'|'image', id: string, saveTo?: unknown, mimeType?: string }} input\n */\nasync function describeArtifacts({ urls, kind, id, saveTo, mimeType }) {\n  const noun = kind === 'image' ? '图片' : '视频';\n  const list = urls.map((url) => `- ${url}`).join('\\n');\n  const wantSave = typeof saveTo === 'string' && saveTo.trim();\n  if (!wantSave) {\n    return `${noun}已生成。以下签名 URL 有时效，请尽快下载或转存：\\n${list}\\n`\n      + '（要直接拿到不过期的文件，下次查询时传 save_to=<绝对路径>，工具会帮你下载到本地。）';\n  }\n\n  const saved = [];\n  const failed = [];\n  // 最多存 4 个：一次生成返回几十个产物时不该把工具调用拖成批量下载。\n  // 整次落盘共享 120 秒预算：单文件也限 120 秒，4 个大视频不会把工具拖到\n  // 宿主超时被杀（那会让用户只看到“查询失败”，却不知道文件已经下了一半）。\n  const saveBudgetMs = 120_000;\n  const saveStartedAt = Date.now();\n  // 序号跟着**成功保存的个数**走：显式文件名下若第一个产物下载失败，\n  // 第二个仍用用户给的原名，而不是莫名变成 -2。\n  for (const url of urls.slice(0, 4)) {\n    const remaining = saveBudgetMs - (Date.now() - saveStartedAt);\n    if (remaining <= 0) {\n      failed.push({ url, reason: '本次落盘的 120 秒预算已用完（产物较多/较大），可减少一次保存的产物再试' });\n      continue;\n    }\n    try {\n      const result = await saveMediaFile(\n        { url, saveTo, id, kind, mimeType, index: saved.length },\n        { timeoutMs: Math.min(120_000, remaining) },\n      );\n      saved.push(result);\n    } catch (error) {\n      failed.push({ url, reason: error?.message || String(error) });\n    }\n  }\n\n  const lines = [];\n  if (saved.length) {\n    lines.push(`${noun}已生成，并已保存到本地（不会过期）：`);\n    for (const item of saved) lines.push(`- ${item.path}（${formatBytes(item.bytes)}）`);\n  }\n  if (saved.length < urls.length) {\n    lines.push(saved.length ? `另外 ${urls.length - saved.length} 个产物未保存：` : `${noun}已生成，但下载到本地失败：`);\n    for (const item of failed) lines.push(`- ${item.reason}`);\n    lines.push('以下签名 URL 仍可临时访问（有时效，请尽快处理）：');\n    for (const url of urls) lines.push(`- ${url}`);\n  }\n  return lines.join('\\n');\n}\n\n/**\n * 媒体接口错误 → 模型能直接转述给用户的话。\n * 提交失败最怕 agent 自动重试：那可能重复计费，所以文案必须明确“不要重提”。\n */\nfunction mediaFailureText(error, { action = 'submit', label = '视频' } = {}) {\n  const status = Number(error?.status) || 0;\n  const code = String(error?.payload?.error?.code || error?.code || '');\n  const upstreamCode = error?.payload?.error?.upstream_code;\n  const retryAfter = Number(error?.retryAfter) || 0;\n  const retryHint = retryAfter > 0 ? `约 ${retryAfter} 秒后` : '稍后';\n  const message = String(error?.message || error || '').slice(0, 300);\n  const noun = label;\n  const statusTool = noun === '图片' ? 'workbuddy_image_status' : 'workbuddy_video_status';\n  const actionText = action === 'submit' ? '提交' : '查询';\n  if (code.endsWith('_NO_OUTPUT')) {\n    return `任务已标记完成，但上游没有返回可下载的 https 产物。稍后再调用 ${statusTool} 查一次；`\n      + '不要重新提交（会再扣一次积分）。';\n  }\n  if (code.endsWith('_KEY_RATE_LIMITED')) {\n    return `申请临时 key 被 Miora 限流（${message || 'HTTP 429'}），生成任务尚未提交、不会计费。`\n      + `${retryHint}直接重试即可，不需要查任务。`;\n  }\n  if (status === 413 || code.endsWith('_PAYLOAD_TOO_LARGE')) {\n    return `${noun}请求体太大（图片 base64 内联会膨胀 1/3）：${message || 'HTTP 413'}。`\n      + '改用 miora fileKey / 公网 https URL，或少带/压缩图片；不要原样重试。';\n  }\n  if (status === 409) {\n    return '任务还没完成，所以没有可下载的产物。稍后再查一次；不要重新提交。';\n  }\n  if (status === 403) {\n    if (code.endsWith('_LOCAL_TOKEN_REQUIRED') || /local token/i.test(message)) {\n      return `${noun}接口只接受本地管理令牌（client key 仅聊天）。检查插件是否用 WORKBUDDY_LOCAL_TOKEN 连桥，或重启桥。`;\n    }\n    if (code.endsWith('_SCOPE_DENIED') || /scope|permission|not authorized/i.test(message)) {\n      return `当前 WorkBuddy 账号没有${noun}生成权限（${message || '403'}）。换有权限的账号；不要重试。`;\n    }\n    return `${noun}请求被上游拒绝（${message || '403'}）。先确认账号权限与登录态，不要原样重试。`;\n  }\n  if (status === 401) {\n    if (code.endsWith('_NO_CREDENTIAL')) {\n      return `读不到 WorkBuddy 登录凭据：在 WorkBuddy 桌面端或插件里重新登录后重试。`;\n    }\n    return `${noun}请求失败：本地桥令牌或 WorkBuddy 登录态不可用。先确认桥在运行且已登录，再重试。`;\n  }\n  if (status === 429) {\n    if (action === 'status') {\n      return `${noun}查询被 Miora 限流：${message || 'HTTP 429'}。任务本身不受影响，`\n        + `${retryHint}重试查询即可；不要重新提交。`;\n    }\n    return `${noun}提交被 Miora 限流：${message || 'HTTP 429'}。`\n      + `任务可能已经创建：${retryHint}先调用 ${statusTool} 查已有任务，不要重复提交。`;\n  }\n  if (status === 400) {\n    return `${noun}请求被拒绝${upstreamCode ? `（上游码 ${upstreamCode}）` : ''}：${message || '参数不合法'}。`\n      + '按提示修改参数或内容，不要原样重试。';\n  }\n  if (status === 404) {\n    return `没有找到这个${noun}任务：${message || 'unknown id'}。确认 id 来自${noun}提交工具的返回；`\n      + '视频和图片的查询接口不互通（不要拿图片 id 查视频，反之亦然）；'\n      + '如果中途切换过 WorkBuddy 账号，任务在提交时的账号下，切回原账号再查。';\n  }\n  if (/ECONNREFUSED|fetch failed|socket hang up/i.test(message)) {\n    return `${noun}请求失败：本地桥未运行。先调用 workbuddy_bridge（action=start），再重试。`;\n  }\n  return `${noun}${actionText}失败：${message || '未知错误'}`\n    + (action === 'submit'\n      ? ' 如果这是超时/断线，任务可能已在上游创建：不要直接重提，先到 WorkBuddy 客户端确认本次任务。'\n      : '');\n}\n\n/**\n * 状态查询的等待预算。\n *\n * 桥单次 `?wait` 上限 60 秒；视频实测 ~101 秒出片，一次 20 秒的查询通常不够。\n * 工具层把用户给的预算按 60 秒一段拆开（段间状态仍是 pending 就继续），\n * 默认 20 秒不变，最多 120 秒 —— 大多数视频能在一个工具调用里等到终态。\n */\nconst MAX_STATUS_WAIT_SECONDS = 120;\nconst STATUS_WAIT_CHUNK_SECONDS = 60;\n\nfunction clampWaitSeconds(raw, fallback = 20) {\n  // null / 空串在“模型没填”的语义下按默认值处理，不能因为 Number(null)=0\n  // 变成立即返回（那会让“默认代等 20 秒”在模型传 null 时失效）。\n  if (raw === undefined || raw === null || raw === '') return fallback;\n  const value = Number(raw);\n  if (!Number.isFinite(value)) return fallback;\n  return Math.min(Math.max(Math.trunc(value), 0), MAX_STATUS_WAIT_SECONDS);\n}\n\n/**\n * 按用户预算查询状态；桥每段最多代等 60 秒。\n * 终态 / 预算用完就停止；每段使用固定的 chunk，不会无限追加。\n */\nasync function waitForMediaStatus(statusFn, id, waitSeconds, signal) {\n  let remaining = waitSeconds;\n  for (;;) {\n    const chunk = Math.min(remaining, STATUS_WAIT_CHUNK_SECONDS);\n    const media = await statusFn(id, { waitMs: chunk * 1000, signal });\n    if (!media || media.status === 'completed' || media.status === 'failed' || media.status === 'cancelled') {\n      return media;\n    }\n    if (remaining <= chunk) return media;\n    remaining -= chunk;\n  }\n}\n\n/**\n * 上游产物里的 miora fileKey。拿到它可以**直接**作为下一次图生图/图生视频的输入，\n * 不必再走 URL 下载 + base64 回传（更快，也不会被签名 URL 的时效卡住）。\n */\nfunction mediaFileKeys(resultFiles) {\n  if (!Array.isArray(resultFiles)) return [];\n  const keys = [];\n  for (const item of resultFiles) {\n    const value = typeof item === 'string'\n      ? item\n      : (item?.fileKey || item?.file_key || item?.file?.fileKey || item?.file?.file_key);\n    if (typeof value === 'string') {\n      const key = value.trim();\n      if (/^(?:bga|file)\\//.test(key) && !keys.includes(key)) keys.push(key);\n    }\n  }\n  return keys;\n}\n\n/**\n * 只有**图片**产物的 fileKey 能直接回流到 images[] / first_frame[]；\n * 视频产物的 fileKey 不是图片，别把它说成“可以当首帧”。\n */\nfunction fileKeyLine(resultFiles, kind) {\n  if (kind !== 'image') return '';\n  const keys = mediaFileKeys(resultFiles);\n  return keys.length ? `可复用的 miora fileKey（下次改图/图生视频直接作为输入，不用重新上传）：\\n${keys.map((key) => `- ${key}`).join('\\n')}` : '';\n}\n\n/** 上游的 mime 可能在顶层或 `{file:{…}}` 里；取第一个可用的。 */\nfunction mediaMimeType(resultFiles) {\n  if (!Array.isArray(resultFiles)) return '';\n  for (const item of resultFiles) {\n    const value = typeof item === 'string'\n      ? ''\n      : (item?.mimeType || item?.mime_type || item?.file?.mimeType || item?.file?.mime_type);\n    if (typeof value === 'string' && value.trim()) return value.trim();\n  }\n  return '';\n}\n\n/**\n * 构造这套工具。\n *\n * @param {object} deps\n * @param {() => object} deps.snapshot 取运行态快照（桥状态 / 目录 / 配置）\n * @param {() => object} deps.supervisor 桥管理器\n * @param {() => object} deps.client 桥客户端\n * @param {() => object} deps.adapter 适配器（读目录缓存）\n * @param {(line: string) => void} deps.log\n */\nexport function createTools(deps) {\n  const { snapshot, supervisor, consoleSupervisor, client, adapter } = deps;\n\n  const statusTool = textTool({\n    name: 'workbuddy_status',\n    description:\n      '查看本机 WorkBuddy 中转的当前状态：本地桥是否在运行、登录账号与令牌剩余有效期、积分余额、可用模型数量、dsh 侧模型路由是否注册成功、控制台地址。'\n      + '排查「WorkBuddy 模型不出现在模型选择器里」时先调用它。'\n      + '需要看逐条请求、趋势图、CSV、账号切换这类明细时，把控制台地址给用户。',\n    parameters: { type: 'object', properties: {}, additionalProperties: false },\n    async execute(_args, exec) {\n      const state = await snapshot({ signal: exec?.signal });\n      const lines = [];\n      lines.push(`桥：${state.bridge.state === 'running' ? '运行中' : state.bridge.state === 'stopped' ? '未运行' : state.bridge.state}`);\n      if (state.bridge.health) {\n        const h = state.bridge.health;\n        lines.push(`  地址：${state.config.bridgeUrl}/v1`);\n        lines.push(`  PID：${h.pid}    已运行：${humanDuration(h.uptimeMs)}`);\n        if (h.auth) {\n          lines.push(`  账号：${h.auth.userId || '(未知)'}`);\n          lines.push(`  令牌：${h.auth.expired ? '已过期（桥会在下次请求时续期）' : `剩余约 ${humanDuration(new Date(h.auth.expiresAt).getTime() - Date.now())}`}`);\n        }\n        lines.push(`  目录：${h.catalogSize ?? 0} 个模型${h.catalogAt ? `（更新于 ${h.catalogAt}）` : ''}`);\n      } else if (state.bridge.error) {\n        lines.push(`  说明：${state.bridge.error}`);\n      }\n      if (state.quota?.ok) {\n        const q = state.quota;\n        const bits = [];\n        if (q.unlimited === true || (typeof q.total === 'number' && q.total < 0)) bits.push('总计 不限量');\n        else if (typeof q.total === 'number') bits.push(`总计 ${q.total}`);\n        for (const p of q.packages || []) bits.push(`${p.name} ${p.remain}/${p.size}`);\n        if (bits.length) {\n          // 归属核对：积分的账号与桥当前账号不一致时必须提醒（换号后缓存尚未换新），\n          // 否则 agent 会把 A 账号的余额当成 B 账号的报给用户\n          if (state.quotaAccount && state.bridgeAccount && state.quotaAccount !== state.bridgeAccount) {\n            lines.push(`积分：⚠ 以下积分属于上一个账号（缓存 ${String(state.quotaAccount).slice(0, 8)}…，桥当前 ${String(state.bridgeAccount).slice(0, 8)}…），正在自动重读`);\n          } else {\n            lines.push(`积分：${bits.join('，')}${state.quotaAccount ? `（账号 ${String(state.quotaAccount).slice(0, 8)}…）` : ''}`);\n          }\n        }\n      } else if (state.quotaError) {\n        lines.push(`积分：读取失败（${state.quotaError}）`);\n      }\n      lines.push(`模型：dsh 侧路由 ${state.route.registered ? '已注册' : '未注册'}（provider=${state.config.provider}），桥目录 ${state.directory.length} 个可用模型`);\n      if (state.route.error) lines.push(`  注册失败：${state.route.error}`);\n      /*\n       * 搜索接入状态要在状态工具里可见：用户报「搜不到 / 401」时，agent 先看这里\n       * 就能分清是 dsh 内置搜索没接桥，还是桥本身没登录，而不是盲猜。\n       */\n      const ws = state.webSearch;\n      if (ws) {\n        const ready = ws.ready === true || (ws.ready === undefined && ws.configured === true);\n        lines.push(ready\n          ? `网页搜索：已接入 WorkBuddy（dsh 内置搜索走桥${ws.lastVerifyFailed ? `；上次自检失败：${ws.lastVerifyError || '未知错误'}` : ''}）`\n          : `网页搜索：dsh 内置搜索未接入 WorkBuddy（${ws.reason || 'unknown'}）${ws.auto?.status ? `；自动接入：${ws.auto.status}${ws.auto.reason ? `/${ws.auto.reason}` : ''}` : ''}`);\n        if (!ready) {\n          lines.push('  修法：插件概览的「网页搜索」卡点「一键接入」，或运行 /workbuddy websearch；');\n          lines.push('  临时兜底：直接调用 `workbuddy_web_search` 工具，它不依赖 dsh 内置搜索配置。');\n        }\n      }\n      const con = state.console || {};\n      lines.push(`控制台：${con.state === 'running' ? `${con.url}（数据界面在这里：逐条请求 / 趋势图 / CSV / 账号切换 / 签到 / 诊断）` : `未运行${con.error ? `（${con.error}）` : ''}`}`);\n      if (state.legacy?.found) lines.push(`注意：检测到旧的 llm-pi-ai workbuddy 路由（${state.legacy.files.join('、')}），与插件重复，建议清理。`);\n      if (state.checkin?.status) {\n        const c = state.checkin.status;\n        lines.push(`签到：${c.todayCheckedIn ? '今日已签' : '今日未签'}${typeof c.streakDays === 'number' ? `，连续 ${c.streakDays} 天` : ''}`);\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  const modelsTool = textTool({\n    name: 'workbuddy_models',\n    description:\n      '列出本机 WorkBuddy 中转当前可用的对话模型（本机已登录账号能真正调用的那些），含上下文长度、单次输出上限与消耗倍率。'\n      + '需要给用户推荐模型、或确认某个模型 ID 是否可用时调用。',\n    parameters: {\n      type: 'object',\n      properties: {\n        refresh: { type: 'boolean', description: 'true 时强制重新向上游拉取目录（默认用缓存，约 1 分钟内有效）' },\n        filter: { type: 'string', description: '可选的模型 ID 子串过滤，例如 \"glm\" 或 \"deepseek\"' },\n      },\n      additionalProperties: false,\n    },\n    async execute(args, exec) {\n      const refresh = args?.refresh === true;\n      const needle = typeof args?.filter === 'string' ? args.filter.toLowerCase() : '';\n      const catalog = await adapter.catalog({ refresh }).catch((error) => { throw new Error(`读取模型目录失败：${error?.message || error}`); });\n      void exec;\n      const list = catalog\n        .filter((m) => m && typeof m.id === 'string')\n        .filter((m) => !needle || m.id.toLowerCase().includes(needle) || String(m.name || '').toLowerCase().includes(needle));\n      if (!list.length) return needle ? `没有匹配 \"${needle}\" 的模型。` : '桥没有返回任何可用模型（先确认桥在运行，且已在「账号」页完成桌面端或插件登录）。';\n      const lines = [`共 ${list.length} 个可用模型：`];\n      for (const m of list) {\n        const bits = [];\n        if (m.context_window) bits.push(`上下文 ${fmtTokens(m.context_window)}`);\n        if (m.max_output_tokens) bits.push(`输出上限 ${fmtTokens(m.max_output_tokens)}`);\n        if (typeof m.credits === 'number') bits.push(m.credits === 0 ? '免费' : `倍率 ${m.credits}`);\n        if (m.supports_images) bits.push('支持图片');\n        // 推理能力与实测档位：面板与 CSV 都有，工具原先没有 —— 同一份目录两处口径\n        if (m.supports_reasoning) {\n          const efforts = Array.isArray(m.reasoning_efforts) ? m.reasoning_efforts : null;\n          bits.push(efforts === null\n            ? '推理（档位未实测）'\n            : (efforts.length ? `推理（${efforts.length} 档：${efforts.join('/')}）` : '推理（网关暂未接）'));\n        }\n        // 当前正在生效的促销（夜间免费 / 夜间折扣）：倍率已经是折后值，\n        // 这行让 agent 能解释“为什么现在是免费/0.395”。\n        if (m.promotion_active === true && m.badge) bits.push(`促销 ${m.badge}（进行中）`);\n        // 上游的 vendor 是单字母内部代号（f/e），对用户没有意义，不显示\n        lines.push(`- ${m.id}（${m.name || m.id}）：${bits.join('，')}`);\n      }\n      lines.push('', '在 dsh 里选择模型时，provider 选 “WorkBuddy” 即可看到这些模型。');\n      return lines.join('\\n');\n    },\n  });\n\n  const usageTool = textTool({\n    name: 'workbuddy_usage',\n    description: '查看本机 WorkBuddy 中转的本地调用账本：最近若干天的调用次数、token 数、消耗积分与失败数，以及积分花在哪些模型上。',\n    parameters: {\n      type: 'object',\n      properties: {\n        days: { type: 'integer', description: '统计最近多少天，1–90，默认 7' },\n      },\n      additionalProperties: false,\n    },\n    async execute(args) {\n      const days = Math.min(Math.max(Number(args?.days) || 7, 1), 90);\n      const usage = await client.usage({ days });\n      const total = usage?.total || {};\n      const videos = Number(total.videos) || 0;\n      const videoFailed = Number(total.videoFailed) || 0;\n      const images = Number(total.images) || 0;\n      const imageFailed = Number(total.imageFailed) || 0;\n      const videoCredit = Number(total.videoCredit) || 0;\n      const videoCreditKnown = Number(total.videoCreditKnown) || 0;\n      const imageCredit = Number(total.imageCredit) || 0;\n      const imageCreditKnown = Number(total.imageCreditKnown) || 0;\n      const genBits = [];\n      if (videos || videoFailed) {\n        genBits.push(`视频提交 ${videos} 次${videoFailed ? `（失败 ${videoFailed}）` : ''}`\n          + `${videoCreditKnown ? `，估算消耗 ${videoCredit.toFixed(2)} 积分` : ''}`);\n      }\n      if (images || imageFailed) {\n        genBits.push(`图片提交 ${images} 次${imageFailed ? `（失败 ${imageFailed}）` : ''}`\n          + `${imageCreditKnown ? `，估算消耗 ${imageCredit.toFixed(2)} 积分` : ''}`);\n      }\n      const videoText = genBits.length ? `，${genBits.join('，')}` : '';\n      const lines = [`最近 ${days} 天：调用 ${total.calls || 0} 次，失败 ${total.failed || 0} 次${videoText}，`\n        + `输入 ${fmtTokens(total.promptTokens)} / 输出 ${fmtTokens(total.completionTokens)} tokens，`\n        + `消耗积分 ${typeof total.credit === 'number' ? total.credit.toFixed(2) : '0'}，平均耗时 ${total.calls ? Math.round((total.ms || 0) / total.calls) : 0} ms`];\n      const models = (usage?.models || []).slice(0, 12);\n      if (models.length) {\n        lines.push('', '按模型：');\n        for (const m of models) {\n          lines.push(`- ${m.model}：${m.calls} 次，积分 ${typeof m.credit === 'number' ? m.credit.toFixed(2) : '0'}，tokens ${fmtTokens((m.promptTokens || 0) + (m.completionTokens || 0))}`);\n        }\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  const checkinTool = textTool({\n    name: 'workbuddy_checkin',\n    description: '查看 WorkBuddy 每日签到状态与连续天数；claim=true 时立即领取当日签到积分。',\n    parameters: {\n      type: 'object',\n      properties: {\n        claim: { type: 'boolean', description: 'true = 立即领取今日签到（会消耗一次上游请求）' },\n      },\n      additionalProperties: false,\n    },\n    async execute(args, exec) {\n      const claim = args?.claim === true;\n      // 桥当前账号（用于归属标注）。**容错取**：快照失败不应炸掉签到主流程，\n      // 那样归属提示最多缺席一行。\n      const state = await snapshot({ signal: exec?.signal }).catch(() => ({}));\n      // 桥凭据异常（degraded）时 checkin 接口会回 502 —— 把它转成可读的\n      // 修法提示，而不是向 agent 抛裸异常（那只会显示一个无上下文的错误码）。\n      let result;\n      try {\n        result = await client.checkin({ claim, signal: exec?.signal });\n      } catch (error) {\n        if (error?.status === 502 || /login|sign in|accessToken|凭据|登录/i.test(String(error?.message))) {\n          return `签到不可用：读不出 WorkBuddy 登录凭据（${error.message || 'HTTP ' + error.status}）。\\n修法：到插件「账号」页重新登录（桌面端或插件登录均可），然后重试。`;\n        }\n        if (error?.status === 401) {\n          return '签到不可用：本地令牌与桥不一致（检查 .env 的 WORKBUDDY_LOCAL_TOKEN，或重启桥）。';\n        }\n        throw error;\n      }\n      const status = result?.status || {};\n      const lines = [];\n      if (claim) {\n        lines.push(result?.ok === false ? `签到失败：${result.error || '未知原因'}` : '已尝试领取今日签到。');\n      }\n      lines.push(`今日：${status.todayCheckedIn ? '已签到' : '未签到'}${typeof status.todayCredit === 'number' ? `（今日获得 ${status.todayCredit}）` : ''}`);\n      if (typeof status.streakDays === 'number') lines.push(`连续签到：${status.streakDays} 天`);\n      if (result?.auto) lines.push(`自动签到：${result.auto.auto ? '开启' : '关闭'}${result.auto.lastError ? `，上次失败：${result.auto.lastError}` : ''}`);\n      // 归属标注：签到状态与积分一样是账号视角的数据 —— 与桥当前账号不一致时说明\n      if (result?.account && state.bridgeAccount && result.account !== state.bridgeAccount) {\n        lines.push(`⚠ 以上签到状态属于上一个账号（缓存 ${String(result.account).slice(0, 8)}…，桥当前 ${String(state.bridgeAccount).slice(0, 8)}…），正在自动重读`);\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  /*\n   * 兜底搜索工具（issue #7）。\n   *\n   * dsh 的内置网页搜索是**宿主配置**：它可能仍指向 DeepSeek、key 失效、或者\n   * 被用户换成了别的后端。用户问的是「插件为什么不能像 WorkBuddy 一样搜」——\n   * 除了自动把宿主配置接过来，还必须给 agent 一条不依赖宿主配置的路：\n   * 直接打桥的 `/v1/web_search`，用 WorkBuddy 自己的搜索额度。\n   */\n  const webSearchTool = textTool({\n    name: 'workbuddy_web_search',\n    description:\n      '用 WorkBuddy 原生网页搜索查资料（不经过 DeepSeek，不需要 DeepSeek key）。'\n      + '当 dsh 内置网页搜索报错（例如 401 / api key invalid）、提示未接入，或你想确保搜索走 WorkBuddy 额度时，用这个工具兜底。'\n      + '返回标题、链接与摘要；需要正文时再对结果 URL 做抓取。',\n    parameters: {\n      type: 'object',\n      properties: {\n        query: { type: 'string', description: '搜索词，至少 2 个字符' },\n        max_results: { type: 'integer', minimum: 1, maximum: 10, description: '返回条数，默认 5' },\n      },\n      required: ['query'],\n      additionalProperties: false,\n    },\n    timeoutMs: 60_000,\n    async execute(args, exec) {\n      const query = typeof args?.query === 'string' ? args.query.trim() : '';\n      if (query.length < 2) throw new Error('query 至少需要 2 个字符');\n      const rawMax = Number(args?.max_results);\n      const maxResults = Number.isFinite(rawMax) ? Math.min(Math.max(Math.trunc(rawMax), 1), 10) : 5;\n      let result;\n      try {\n        result = await client.webSearch({ query, maxResults, signal: exec?.signal });\n      } catch (error) {\n        if (error?.status === 401) {\n          throw new Error('网页搜索失败：本地桥令牌与插件不一致。先重启桥；仍失败就检查 WORKBUDDY_LOCAL_TOKEN。', { cause: error });\n        }\n        if (error?.status === 429) {\n          return `WorkBuddy 搜索被限流了（${error.message || 'HTTP 429'}）。等一会儿再试，或减少搜索次数。`;\n        }\n        if (/ECONNREFUSED|fetch failed|socket hang up/i.test(String(error?.message || ''))) {\n          return '网页搜索失败：本地桥未运行。先调用 workbuddy_bridge（action=start），再重试。';\n        }\n        throw new Error(`网页搜索失败：${error?.message || error}`, { cause: error });\n      }\n      const results = Array.isArray(result?.results) ? result.results : [];\n      if (!results.length) return `WorkBuddy 没有搜到与「${query}」相关的结果。换个关键词或英文关键词再试。`;\n      const lines = [`WorkBuddy 网页搜索（${result.provider || 'workbuddy'}）：${results.length} 条`];\n      results.forEach((item, index) => {\n        lines.push(`${index + 1}. ${item.title || item.url}`);\n        lines.push(`   ${item.url}`);\n        if (item.snippet) lines.push(`   ${item.snippet}`);\n      });\n      return lines.join('\\n');\n    },\n  });\n\n  /*\n   * 视频生成工具（Miora）。\n   *\n   * 视频是**高积分计费**能力，而且上游是异步任务：提交只返回任务 id，\n   * 生成可能持续几分钟。所以拆成 submit / status 两个工具，避免一次工具调用\n   * 阻塞十几分钟；同时用文案明确“同一需求不要重复提交”，防止 agent 自动重试\n   * 造成重复扣费。\n   */\n  const videoSubmitTool = textTool({\n    name: 'workbuddy_generate_video',\n    description:\n      '用 WorkBuddy 的 Miora 生成视频：支持文生视频、首帧（可选尾帧）生视频、参考图生视频。'\n      + '这是高积分计费操作，**只在用户明确要求生成视频时调用**；同一需求只提交一次。'\n      + '提交是异步的：本工具返回任务 id，之后用 workbuddy_video_status 查询；'\n      + '不要因为等待时间长就重复提交（会重复扣费）。'\n      + '图片输入（first_frame / last_frame / references[]）请**传字符串**：'\n      + '本地绝对路径、公网 https URL、data URI 或 miora fileKey。'\n      + '如果上游返回了 fileKey，后续图生视频优先复用它（不必重新上传）。'\n      + '多张图以 base64 内联时合计受桥请求体限制（默认 32 MB）；超了会提示改用 fileKey/URL。'\n      + '参数会严格校验：拼错的键（如 size / image）会直接返回 400，而不是被忽略后按文生视频计费。',\n    parameters: {\n      type: 'object',\n      properties: {\n        prompt: { type: 'string', description: '视频描述；文生视频/参考图必填，首尾帧模式可选（描述运动与镜头）' },\n        mode: { type: 'string', enum: ['text', 'frame', 'reference'], description: '不传时按输入自动推断' },\n        first_frame: {\n          type: 'string',\n          description: '起始帧（字符串）：绝对本地路径 / 公网 https URL / data URI / miora fileKey',\n        },\n        last_frame: { type: 'string', description: '结束帧（可选，字符串），格式同 first_frame' },\n        references: {\n          type: 'array',\n          items: { type: 'string' },\n          description: '参考图（字符串数组，一张或多张），格式同 first_frame',\n        },\n        duration: { type: 'integer', minimum: 1, description: '目标时长（正整数秒）。本次实测支持 4–15 秒，3 秒会被上游拒绝' },\n        resolution: { type: 'string', description: '分辨率。本次实测支持 768P / 2K（大小写不敏感），720p 会被上游拒绝' },\n        aspect_ratio: { type: 'string', description: '画幅，如 16:9 / 9:16 / 1:1' },\n        save_to: {\n          type: 'string',\n          description: '可选：绝对路径（目录或完整文件名）。上游同步完成时直接落盘并返回文件路径；'\n            + '异步任务仍用 workbuddy_video_status 的 save_to 下载',\n        },\n      },\n      additionalProperties: false,\n    },\n    timeoutMs: 410_000,\n    async execute(args, exec) {\n      /*\n       * 先把图片输入归一化。这一步**在调用桥之前**做，且失败就直接返回说明：\n       * 原先用 `typeof === 'string'` 静默过滤，模型把 first_frame 写成\n       * `{path: …}` 时图片被丢掉，请求退化成文生视频却照样计费。\n       */\n      let firstFrame;\n      let lastFrame;\n      let references;\n      try {\n        firstFrame = args?.first_frame === undefined || args.first_frame === null\n          ? ''\n          : imageInputString(args.first_frame, 'first_frame');\n        lastFrame = args?.last_frame === undefined || args.last_frame === null\n          ? ''\n          : imageInputString(args.last_frame, 'last_frame');\n        references = imageInputList(args?.references, 'references');\n      } catch (error) {\n        return `视频参数无法识别，没有提交（未计费）：${error.message}\n修法：图片输入统一用字符串（本地绝对路径 / 公网 https URL / data URI / miora fileKey），然后原样重试本次提交。`;\n      }\n      if (args?.prompt !== undefined && args?.prompt !== null && typeof args.prompt !== 'string') {\n        return '视频 prompt 必须是字符串；这次没有提交（未计费）。';\n      }\n      let video;\n      try {\n        video = await client.videoSubmit({\n          prompt: typeof args?.prompt === 'string' ? args.prompt : '',\n          // 显式给了但类型不对时**透传给桥**，让桥的严格校验报 400；\n          // 这里如果按 typeof 过滤，会把“resolution: 1080”静默变成默认分辨率。\n          mode: args?.mode ?? '',\n          firstFrame,\n          lastFrame,\n          references,\n          duration: args?.duration,\n          resolution: args?.resolution ?? '',\n          aspectRatio: args?.aspect_ratio ?? '',\n          signal: exec?.signal,\n        });\n      } catch (error) {\n        return mediaFailureText(error, { action: 'submit', label: '视频' });\n      }\n      const summary = `任务：${video.id}；状态：${video.status}（上游：${video.upstream_status || '-'}）；`\n        + `模式：${video.mode || '-'}`\n        + `${video.seconds ? `；时长：${video.seconds}s` : ''}`\n        + `${video.resolution ? `；分辨率：${video.resolution}` : ''}`\n        + `${video.aspect_ratio ? `；画幅：${video.aspect_ratio}` : ''}`\n        + `${video.model ? `；模型：${video.model}` : ''}`;\n      /*\n       * 上游可能同步完成（mode=sync）：结果/失败原因就在这次响应里，按 id 再查\n       * 只会得到 INVALID_TASK_ID_FOR_SYNC_MODE。这类终态必须在这里讲清楚，\n       * 不能再说“已提交，稍后查询”。\n       */\n      if (video.status === 'completed') {\n        const urls = Array.isArray(video.output?.urls) ? video.output.urls : [];\n        const lines = [\n          video.sync ? '视频已生成（上游同步返回完成）。' : '视频已生成（上游返回完成）。',\n          summary,\n          '本次提交按 WorkBuddy 账号积分计费（以余额为准）。',\n        ];\n        if (urls.length) {\n          lines.push(await describeArtifacts({\n            urls, kind: 'video', id: video.id, saveTo: args?.save_to, mimeType: mediaMimeType(video.result_files),\n          }));\n        } else if (video.sync) {\n          lines.push('上游同步标记完成，但没有返回可下载的 https 产物；这个任务按 id 查不到更多信息。'\n            + '不要再按 id 重查；需要产物请向用户确认后重新生成（会再次计费）。');\n        } else {\n          lines.push('上游标记完成，但这次响应没有可下载的 https 产物。稍后可用 workbuddy_video_status 再查一次（查询不计费）。');\n        }\n        lines.push('同一需求不要重复生成（会再次计费）。');\n        return lines.join('\\n');\n      }\n      if (video.status === 'failed' || video.status === 'cancelled') {\n        const lines = [\n          video.status === 'cancelled'\n            ? (video.sync ? '视频任务已取消（上游同步返回）。' : '视频任务已取消。')\n            : (video.sync ? '视频生成失败（上游同步返回失败）。' : '视频生成失败。'),\n          summary,\n          `原因：${video.error?.message || '上游未给失败原因'}`,\n          '本次没有可交付产物。不要原样重提；先和用户确认是否调整参数/内容，再决定是否重新生成（会再次计费）。',\n        ];\n        return lines.join('\\n');\n      }\n      const lines = [\n        `已提交视频任务：${video.id}`,\n        summary,\n        '提交成功即按 WorkBuddy 账号积分计费。同一需求不要再提交一次。',\n        `生成是异步的，稍后用 workbuddy_video_status 查询（id=${video.id}，可一次代等最多 120 秒）；completed 后把返回的 URL 交给用户。`,\n      ];\n      if (args?.save_to) {\n        lines.push('本次 save_to 只对“提交时已同步完成”的产物生效；异步任务完成后再查状态时请再传一次 save_to。');\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  const videoStatusTool = textTool({\n    name: 'workbuddy_video_status',\n    description:\n      '查询 workbuddy_generate_video 提交的视频任务状态。'\n      + '默认会在本工具里等待最多 20 秒、可用 wait_seconds 最高 120 秒（桥代轮询），通常能直接拿到 completed；'\n      + 'queued/in_progress 时告诉用户还在生成，稍后再查，**不要重新提交**；'\n      + 'completed 时返回有时效的下载 URL；failed/cancelled 时返回失败原因。'\n      + '产物是**会过期**的签名 URL：要交付给用户时请传 save_to（绝对路径，目录或文件），'\n      + '工具会把视频下载到本地并返回真实文件路径 —— 否则链接过期后只能重新生成（再扣一次积分）。'\n      + '一次调用最多保存前 4 个产物，其余仍返回 URL。',\n    parameters: {\n      type: 'object',\n      properties: {\n        id: { type: 'string', description: '提交视频时返回的任务 id（upstreamTaskId）' },\n        wait_seconds: {\n          type: 'integer',\n          minimum: 0,\n          maximum: 120,\n          description: '在本工具内等待多少秒再返回（0 = 立即返回；默认 20，最大 120；'\n            + '内部按桥的 60 秒一段轮询，视频通常一次就能等到终态）',\n        },\n        save_to: {\n          type: 'string',\n          description: '可选：绝对路径（目录或完整文件名）。给定时把产物下载到本地并返回文件路径，'\n            + '目录会自动创建；不给则只返回签名 URL',\n        },\n      },\n      required: ['id'],\n      additionalProperties: false,\n    },\n    // 查询最多等 180 秒（60+60 两段 + 查询余量），落盘再预留 120 秒。\n    timeoutMs: 330_000,\n    async execute(args, exec) {\n      const id = typeof args?.id === 'string' ? args.id.trim() : '';\n      if (!id) throw new Error('id 不能为空：请传 workbuddy_generate_video 返回的任务 id');\n      const waitSeconds = clampWaitSeconds(args?.wait_seconds);\n      let video;\n      try {\n        video = await waitForMediaStatus(\n          (taskId, options) => client.videoStatus(taskId, options),\n          id,\n          waitSeconds,\n          exec?.signal,\n        );\n      } catch (error) {\n        return mediaFailureText(error, { action: 'status', label: '视频' });\n      }\n      const lines = [\n        `任务 ${id}：${video.status}（上游：${video.upstream_status || '-'}）`,\n        `模式：${video.mode || '-'}${video.seconds ? `；时长：${video.seconds}s` : ''}`\n          + `${video.resolution ? `；分辨率：${video.resolution}` : ''}`\n          + `${video.aspect_ratio ? `；画幅：${video.aspect_ratio}` : ''}`,\n      ];\n      if (video.created_at) {\n        lines.push(`提交时间：${new Date(video.created_at * 1000).toISOString()}`);\n      }\n      if (video.status === 'completed') {\n        const urls = Array.isArray(video.output?.urls) ? video.output.urls : [];\n        if (urls.length) {\n          lines.push(await describeArtifacts({\n            urls, kind: 'video', id, saveTo: args?.save_to, mimeType: mediaMimeType(video.result_files),\n          }));\n        } else if (video.sync) {\n          lines.push('上游同步标记完成，但没有返回 https 产物。同步任务按 id 查不到更多信息；'\n            + '不要再重查，需要产物请向用户确认后重新生成（会再次计费）。');\n        } else {\n          lines.push('上游标记完成，但没有返回 https 产物 URL。稍后再查一次，或到 WorkBuddy 客户端查看该任务。');\n        }\n      } else if (video.sync_result_unavailable\n        || /INVALID_TASK_ID_FOR_SYNC_MODE/i.test(video.error?.message || '')) {\n        lines.push('这次查询没有拿到结果：该任务在上游是**同步完成**的，结果只出现在提交响应里，'\n          + '桥的短期缓存已不包含它（过期、重启，或当前不是提交时的账号）。'\n          + '如果刚切换过账号，切回提交时的账号再查；不要把它当成普通失败反复重提，'\n          + '需要产物时请向用户确认后重新生成（会再次计费）。');\n      } else if (video.status === 'failed' || video.status === 'cancelled') {\n        lines.push(video.status === 'cancelled'\n          ? '任务已取消（不是生成失败）：没有产物。'\n          : `任务未成功：${video.error?.message || '上游未给失败原因'}`);\n        if (video.sync) lines.push('（该任务是上游同步完成的，结果来自提交缓存。）');\n        lines.push('不要直接重复提交；先确认失败原因/用户意愿，必要时再生成。');\n      } else {\n        lines.push(waitSeconds > 0\n          ? `仍在生成（本次最多等待约 ${waitSeconds} 秒）。稍后再调用本工具查询；不要重新提交，否则会重复计费。`\n          : '仍在生成。稍后再调用本工具查询；不要重新提交，否则会重复计费。');\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  /*\n   * 图片生成工具（Miora）。\n   *\n   * 与视频同一套纪律：提交只拿任务 id、不阻塞等出图；文案明确高积分计费且\n   * 禁止同一需求重复提交（会重复扣费）。\n   */\n  const imageSubmitTool = textTool({\n    name: 'workbuddy_generate_image',\n    description:\n      '用 WorkBuddy 的 Miora 生成图片：只给 prompt 是文生图；同时给 images[] 就是图生图（按指令改图）。'\n      + '这是高积分计费操作，**只在用户明确要求生成/修改图片时调用**；同一需求只提交一次。'\n      + '提交是异步的：本工具返回任务 id，之后用 workbuddy_image_status 查询；'\n      + '不要因为等待时间长就重复提交（会重复扣费）。'\n      + '图片输入请**传字符串**：本地绝对路径、公网 https URL、data URI 或 miora fileKey。'\n      + '如果上游返回了 fileKey，后续改图优先复用它（不必重新上传）。'\n      + '多张图以 base64 内联时合计受桥请求体限制（默认 32 MB）；超了会提示改用 fileKey/URL。'\n      + '参数会严格校验：拼错的键（如 aspect_ratio / width）会直接返回 400，而不是被忽略。',\n    parameters: {\n      type: 'object',\n      properties: {\n        prompt: { type: 'string', description: '图片描述（文生图）或修改指令（图生图）。必填' },\n        images: {\n          type: 'array',\n          items: { type: 'string' },\n          description: '参考图字符串数组（给了就是图生图）：绝对本地路径 / 公网 https URL / data URI / miora fileKey，每张 ≤ 20 MB',\n        },\n        size: { type: 'string', description: '输出尺寸 WIDTHxHEIGHT，如 1024x1024；不传用模型默认' },\n        quality: { type: 'string', description: '文生图的质量档（如 standard / hd），图生图忽略' },\n        save_to: {\n          type: 'string',\n          description: '可选：绝对路径（目录或完整文件名）。上游同步完成时直接落盘并返回文件路径；'\n            + '异步任务仍用 workbuddy_image_status 的 save_to 下载',\n        },\n      },\n      required: ['prompt'],\n      additionalProperties: false,\n    },\n    timeoutMs: 410_000,\n    async execute(args, exec) {\n      /*\n       * 与视频同一道防线：图片输入认不出来时**不要提交**。\n       * 原先非字符串项被静默过滤，模型传 `images: [{url: …}]` 时会变成\n       * `images: []` → 请求退化成文生图 → 图没带上但照常计费。\n       */\n      let images;\n      try {\n        images = imageInputList(args?.images, 'images');\n      } catch (error) {\n        return `图片参数无法识别，没有提交（未计费）：${error.message}\n修法：images[] 每项都用字符串（本地绝对路径 / 公网 https URL / data URI / miora fileKey），然后原样重试本次提交。`;\n      }\n      if (args?.prompt !== undefined && args?.prompt !== null && typeof args.prompt !== 'string') {\n        return '图片 prompt 必须是字符串；这次没有提交（未计费）。';\n      }\n      const mode = images.length ? 'edit' : 'generate';\n      let image;\n      try {\n        image = await client.imageSubmit({\n          prompt: typeof args?.prompt === 'string' ? args.prompt : '',\n          images,\n          // 同视频：类型不对的值交给桥报 400，不能静默忽略后按默认尺寸生成。\n          size: args?.size ?? '',\n          quality: args?.quality ?? '',\n          mode,\n          signal: exec?.signal,\n        });\n      } catch (error) {\n        return mediaFailureText(error, { action: 'submit', label: '图片' });\n      }\n      const summary = `任务：${image.id}；状态：${image.status}（上游：${image.upstream_status || '-'}）；`\n        + `模式：${image.mode || mode}`\n        + `${image.size ? `；尺寸：${image.size}` : ''}${image.model ? `；模型：${image.model}` : ''}`;\n      /*\n       * 图片实测经常走 `mode:\"sync\"`：结果（或失败原因）就在这次提交响应里，\n       * 按 id 再查只会得到 INVALID_TASK_ID_FOR_SYNC_MODE。终态必须当场讲清楚。\n       */\n      if (image.status === 'completed') {\n        const urls = Array.isArray(image.output?.urls) ? image.output.urls : [];\n        const lines = [\n          image.sync ? '图片已生成（上游同步返回完成）。' : '图片已生成（上游返回完成）。',\n          summary,\n          '本次提交按 WorkBuddy 账号积分计费（以余额为准）。',\n        ];\n        if (urls.length) {\n          lines.push(await describeArtifacts({\n            urls, kind: 'image', id: image.id, saveTo: args?.save_to, mimeType: mediaMimeType(image.result_files),\n          }));\n        } else if (image.sync) {\n          lines.push('上游同步标记完成，但没有返回可下载的 https 产物；这个任务按 id 查不到更多信息。'\n            + '不要再按 id 重查；需要产物请向用户确认后重新生成（会再次计费）。');\n        } else {\n          lines.push('上游标记完成，但这次响应没有可下载的 https 产物。稍后可用 workbuddy_image_status 再查一次（查询不计费）。');\n        }\n        const keys = fileKeyLine(image.result_files, 'image');\n        if (keys) lines.push(keys);\n        lines.push('同一需求不要重复生成（会再次计费）。');\n        return lines.join('\\n');\n      }\n      if (image.status === 'failed' || image.status === 'cancelled') {\n        const lines = [\n          image.status === 'cancelled'\n            ? (image.sync ? '图片任务已取消（上游同步返回）。' : '图片任务已取消。')\n            : (image.sync ? '图片生成失败（上游同步返回失败）。' : '图片生成失败。'),\n          summary,\n          `原因：${image.error?.message || '上游未给失败原因'}`,\n          '本次没有可交付产物。不要原样重提；先和用户确认是否调整提示词/参考图，再决定是否重新生成（会再次计费）。',\n        ];\n        const keys = fileKeyLine(image.result_files, 'image');\n        if (keys) lines.push(keys);\n        return lines.join('\\n');\n      }\n      const lines = [\n        `已提交图片任务：${image.id}`,\n        summary,\n        '提交成功即按 WorkBuddy 账号积分计费。同一需求不要再提交一次。',\n        `生成是异步的，稍后用 workbuddy_image_status 查询（id=${image.id}，可一次代等最多 120 秒）；completed 后把返回的 URL 交给用户。`,\n      ];\n      if (args?.save_to) {\n        lines.push('本次 save_to 只对“提交时已同步完成”的产物生效；异步任务完成后再查状态时请再传一次 save_to。');\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  const imageStatusTool = textTool({\n    name: 'workbuddy_image_status',\n    description:\n      '查询 workbuddy_generate_image 提交的图片任务状态。'\n      + '默认会在本工具里等待最多 20 秒、可用 wait_seconds 最高 120 秒（桥代轮询），通常能直接拿到 completed；'\n      + 'queued/in_progress 时告诉用户还在生成，稍后再查，**不要重新提交**；'\n      + 'completed 时返回有时效的下载 URL；failed/cancelled 时返回失败原因。'\n      + '产物是**会过期**的签名 URL：要交付给用户时请传 save_to（绝对路径，目录或文件），'\n      + '工具会把图片下载到本地并返回真实文件路径 —— 否则链接过期后只能重新生成（再扣一次积分）。'\n      + '一次调用最多保存前 4 个产物，其余仍返回 URL。',\n    parameters: {\n      type: 'object',\n      properties: {\n        id: { type: 'string', description: '提交图片时返回的任务 id（upstreamTaskId）' },\n        wait_seconds: {\n          type: 'integer',\n          minimum: 0,\n          maximum: 120,\n          description: '在本工具内等待多少秒再返回（0 = 立即返回；默认 20，最大 120；'\n            + '内部按桥的 60 秒一段轮询）',\n        },\n        save_to: {\n          type: 'string',\n          description: '可选：绝对路径（目录或完整文件名）。给定时把产物下载到本地并返回文件路径，'\n            + '目录会自动创建；不给则只返回签名 URL',\n        },\n      },\n      required: ['id'],\n      additionalProperties: false,\n    },\n    // 查询最多等 180 秒（60+60 两段 + 查询余量），落盘再预留 120 秒。\n    timeoutMs: 330_000,\n    async execute(args, exec) {\n      const id = typeof args?.id === 'string' ? args.id.trim() : '';\n      if (!id) throw new Error('id 不能为空：请传 workbuddy_generate_image 返回的任务 id');\n      const waitSeconds = clampWaitSeconds(args?.wait_seconds);\n      let image;\n      try {\n        image = await waitForMediaStatus(\n          (taskId, options) => client.imageStatus(taskId, options),\n          id,\n          waitSeconds,\n          exec?.signal,\n        );\n      } catch (error) {\n        return mediaFailureText(error, { action: 'status', label: '图片' });\n      }\n      const lines = [\n        `任务 ${id}：${image.status}（上游：${image.upstream_status || '-'}）`,\n        `模式：${image.mode || '-'}${image.size ? `；尺寸：${image.size}` : ''}`\n          + `${image.quality ? `；质量：${image.quality}` : ''}`,\n      ];\n      if (image.created_at) lines.push(`提交时间：${new Date(image.created_at * 1000).toISOString()}`);\n      if (image.status === 'completed') {\n        const urls = Array.isArray(image.output?.urls) ? image.output.urls : [];\n        if (urls.length) {\n          lines.push(await describeArtifacts({\n            urls, kind: 'image', id, saveTo: args?.save_to, mimeType: mediaMimeType(image.result_files),\n          }));\n        } else if (image.sync) {\n          lines.push('上游同步标记完成，但没有返回 https 产物。同步任务按 id 查不到更多信息；'\n            + '不要再重查，需要产物请向用户确认后重新生成（会再次计费）。');\n        } else {\n          lines.push('上游标记完成，但没有返回 https 产物 URL。稍后再查一次，或到 WorkBuddy 客户端查看该任务。');\n        }\n        const keys = fileKeyLine(image.result_files, 'image');\n        if (keys) lines.push(keys);\n      } else if (image.sync_result_unavailable\n        || /INVALID_TASK_ID_FOR_SYNC_MODE/i.test(image.error?.message || '')) {\n        lines.push('这次查询没有拿到结果：该任务在上游是**同步完成**的，结果只出现在提交响应里，'\n          + '桥的短期缓存已不包含它（过期、重启，或当前不是提交时的账号）。'\n          + '如果刚切换过账号，切回提交时的账号再查；不要把它当成普通失败反复重提，'\n          + '需要产物时请向用户确认后重新生成（会再次计费）。');\n      } else if (image.status === 'failed' || image.status === 'cancelled') {\n        lines.push(image.status === 'cancelled'\n          ? '任务已取消（不是生成失败）：没有产物。'\n          : `任务未成功：${image.error?.message || '上游未给失败原因'}`);\n        if (image.sync) lines.push('（该任务是上游同步完成的，结果来自提交缓存。）');\n        lines.push('不要直接重复提交；先确认失败原因/用户意愿，必要时再生成。');\n      } else {\n        lines.push(waitSeconds > 0\n          ? `仍在生成（本次最多等待约 ${waitSeconds} 秒）。稍后再调用本工具查询；不要重新提交，否则会重复计费。`\n          : '仍在生成。稍后再调用本工具查询；不要重新提交，否则会重复计费。');\n      }\n      return lines.join('\\n');\n    },\n  });\n\n  const bridgeTool = textTool({\n    name: 'workbuddy_bridge',\n    description:\n      '管理本机 WorkBuddy 的本地桥进程：status 查看、start 拉起（已运行则复用）、stop 停止、restart 重启。'\n      + '模型报「本地桥不可用 / ECONNREFUSED」时用 restart。'\n      + 'action=console 则确保数据控制台在运行并返回它的地址（看逐条请求 / 趋势图 / CSV 用那个页面）。',\n    parameters: {\n      type: 'object',\n      properties: {\n        action: { type: 'string', enum: ['status', 'start', 'stop', 'restart', 'console'], description: '要执行的动作，默认 status' },\n      },\n      required: ['action'],\n      additionalProperties: false,\n    },\n    timeoutMs: 60_000,\n    async execute(args, exec) {\n      const action = String(args?.action || 'status');\n      if (action === 'console') {\n        const result = await consoleSupervisor.ensure({ signal: exec?.signal });\n        if (!result.ok) return `控制台启动失败：${result.error}`;\n        const probe = await consoleSupervisor.probe({ cached: false });\n        return `控制台已就绪：${consoleSupervisor.url}${result.reused ? '（复用已在运行的实例）' : '（本次新拉起）'}\\n状态：${probe.state}`\n          + '\\n逐条请求、趋势图、CSV 导出、账号切换、签到与诊断都在这个页面上。';\n      }\n      if (action === 'status') {\n        const probe = await supervisor.probe(exec?.signal);\n        if (probe.state === 'running') {\n          return `桥运行中：pid ${probe.health.pid}，已运行 ${humanDuration(probe.health.uptimeMs)}，地址 ${supervisor.baseUrl}/v1`;\n        }\n        return `桥未运行（${probe.state}）：${probe.error || ''}`;\n      }\n      if (action === 'stop') {\n        const result = await supervisor.stop(exec?.signal);\n        return result.ok ? (result.stopped ? '已停止桥。' : '桥本来就没在运行。') : `停止失败：${result.error}`;\n      }\n      if (action === 'restart') {\n        const result = await supervisor.ensure({ restart: true, signal: exec?.signal });\n        adapter.invalidate();\n        return result.ok ? `桥已重启：pid ${result.health?.pid}，地址 ${supervisor.baseUrl}/v1` : `重启失败：${result.error}`;\n      }\n      const result = await supervisor.ensure({ signal: exec?.signal });\n      adapter.invalidate();\n      return result.ok\n        ? `桥已就绪${result.reused ? '（复用已在运行的实例）' : '（新拉起）'}：pid ${result.health?.pid}，地址 ${supervisor.baseUrl}/v1`\n        : `启动失败：${result.error}`;\n    },\n  });\n\n  return [\n    statusTool, modelsTool, usageTool, checkinTool, webSearchTool,\n    videoSubmitTool, videoStatusTool, imageSubmitTool, imageStatusTool, bridgeTool,\n  ];\n}\n"
    },
    {
      "path": "dsh-plugin/lib/web-search-config.mjs",
      "content": "/**\n * 把 dsh 内置的 Web search provider 一键指向 WorkBuddy 本地桥。\n *\n * 只改两处：\n *   - `web-search-deepseek.baseURL` → 本地桥 `/v1`（provider 会追加 `/messages`）；\n *   - `web-search-deepseek.apiKeyEnv` → 一个**独立**的凭据引用\n *     `WORKBUDDY_SEARCH_BRIDGE_KEY`，值为桥本地令牌。\n * 不改用户的 `DEEPSEEK_API_KEY`，也不把令牌写进 settings/patch 文件。\n *\n * 这两个服务由 dsh 宿主提供；插件不 import dsh 内部包，保持 vendor 形态可用。\n */\n\nexport const WEB_SEARCH_ENTRY_ID = 'web-search-deepseek';\nexport const WEB_ENTRY_ID = 'web';\nexport const SEARCH_KEY_REF = 'WORKBUDDY_SEARCH_BRIDGE_KEY';\n\n/**\n * @param {object} deps\n * @param {{ update: (ns: string, patch: object) => Promise<void>, get?: (ns: string) => unknown }} deps.settings\n * @param {{ set: (ref: string, value: string) => Promise<void> }} deps.credentials\n * @param {string} deps.baseURL 例如 http://127.0.0.1:8790/v1\n * @param {string} deps.token 桥本地令牌\n * @returns {Promise<{ baseURL: string, provider: string, apiKeyRef: string, providerSelected: boolean, clearedLiteralKey: boolean }>}\n */\nexport async function configureWorkBuddyWebSearch({ settings, credentials, baseURL, token }) {\n  if (!settings || typeof settings.update !== 'function') {\n    throw new Error('dsh settings service is unavailable; cannot configure web search');\n  }\n  if (!credentials || typeof credentials.set !== 'function') {\n    throw new Error('dsh credentials service is unavailable; cannot store the bridge token');\n  }\n  if (typeof baseURL !== 'string' || !/^https?:\\/\\//i.test(baseURL)) {\n    throw new Error('invalid bridge base URL for web search');\n  }\n  if (typeof token !== 'string' || token.length === 0) {\n    throw new Error('bridge local token is empty; start the bridge first');\n  }\n\n  // 1) 独立凭据引用：不碰 DEEPSEEK_API_KEY，避免影响其它 DeepSeek 功能。\n  await credentials.set(SEARCH_KEY_REF, token);\n\n  /*\n   * 2) 确保选中的是 Messages provider（baseURL/apiKeyEnv 属于它）。\n   *\n   * 只有 dsh 把 `web` 注册成 settings 分节时才写；rc.6 的 provider 选择在\n   * bundle patch 里（默认就是 deepseek-official），并不存在 `web` 分节。\n   * 无条件 update 会直接抛 \"namespace is not registered\"，把一键配置打断。\n   */\n  let providerSelected = false;\n  /*\n   * 真实 dsh 的 settings 服务没有 `get(ns)`，只有 `describe()`；这里必须用\n   * describe 判断 `web` 分节是否存在，否则永远跳过 provider 选择。\n   */\n  const config = readWebSearchConfig(settings);\n  const hasWebSection = config.hasWeb;\n  if (hasWebSection) {\n    await settings.update(WEB_ENTRY_ID, { searchProvider: 'deepseek-official' });\n    providerSelected = true;\n  }\n\n  // 3) 指向桥，并使用上面的独立引用。\n  const patch = { baseURL, apiKeyEnv: SEARCH_KEY_REF };\n  // 老配置可能把字面 apiKey 写进了分节；provider 会优先用它，导致桥令牌被忽略。\n  // 置空即可回落到 apiKeyEnv，同时不把任何秘密写进 settings/patch。\n  const current = config.section;\n  const clearedLiteralKey = Boolean(current && typeof current === 'object'\n    && typeof current.apiKey === 'string' && current.apiKey.length > 0);\n  if (clearedLiteralKey) patch.apiKey = '';\n  await settings.update(WEB_SEARCH_ENTRY_ID, patch);\n\n  return {\n    baseURL,\n    provider: 'deepseek-official',\n    apiKeyRef: SEARCH_KEY_REF,\n    providerSelected,\n    clearedLiteralKey,\n  };\n}\n\n/**\n * 在一键接入前备份 dsh 的搜索配置，供“恢复原配置”使用。\n *\n * 返回值里的 `credential` 是上一份桥令牌，只允许留在插件内存中；\n * 对外的 `summary` 不含令牌，可直接放进状态快照给面板。\n *\n * @param {object} deps\n * @param {{ get?: (ns: string) => unknown, describe?: () => Array<{ ns: string, user?: unknown }>, replace?: (ns: string, section: object) => Promise<void> }} deps.settings\n * @param {{ resolve?: (ref: string) => Promise<{ value: string } | undefined>, set?: (ref: string, value: string) => Promise<void>, unset?: (ref: string) => Promise<void> }} deps.credentials\n * @returns {Promise<{ ok: boolean, at: number, section: object | null, webSection: object | null, credential: string | null, summary: { baseURL: string, apiKeyRef: string, hadLiteralKey: boolean, provider: string } }>}\n */\nexport async function snapshotWorkBuddyWebSearch({ settings, credentials } = {}) {\n  const snapshot = {\n    ok: false,\n    at: Date.now(),\n    section: null,\n    webSection: null,\n    credential: null,\n    summary: { baseURL: '', apiKeyRef: '', hadLiteralKey: false, provider: '' },\n  };\n  /*\n   * 真实 dsh 的 settings 服务**没有 get(ns)**，只有 describe/update/replace。\n   * 原先强制要求 get，导致生产环境快照永远 ok:false —— \"恢复原配置\"不可达，\n   * 撤销只能走\"按指纹删键\"的兜底，可能误删用户自己的同名本机端点。\n   */\n  if (!settings || (typeof settings.get !== 'function' && typeof settings.describe !== 'function')) return snapshot;\n  if (!settings.replace || typeof settings.replace !== 'function') return snapshot;\n  if (!credentials || typeof credentials.resolve !== 'function'\n    || typeof credentials.set !== 'function' || typeof credentials.unset !== 'function') {\n    return snapshot;\n  }\n\n  let section;\n  let webSection;\n  let sectionExists = false;\n  let webExists = false;\n  try {\n    /*\n     * 优先用 describe() 的 **user 层**：get() 返回的是 base/default 合并后的\n     * 解析值，直接写回去会把 base 里的密钥或默认值“固化”成用户覆盖。\n     */\n    if (typeof settings.describe === 'function') {\n      const descriptors = settings.describe();\n      const list = Array.isArray(descriptors) ? descriptors : [];\n      const searchDesc = list.find((item) => item && item.ns === WEB_SEARCH_ENTRY_ID);\n      const webDesc = list.find((item) => item && item.ns === WEB_ENTRY_ID);\n      sectionExists = Boolean(searchDesc);\n      webExists = Boolean(webDesc);\n      section = searchDesc\n        ? (searchDesc.user && typeof searchDesc.user === 'object' && !Array.isArray(searchDesc.user)\n          ? { ...searchDesc.user }\n          : {})\n        : null;\n      webSection = webDesc\n        ? (webDesc.user && typeof webDesc.user === 'object' && !Array.isArray(webDesc.user)\n          ? { ...webDesc.user }\n          : {})\n        : null;\n    } else {\n      section = settings.get(WEB_SEARCH_ENTRY_ID);\n      webSection = settings.get(WEB_ENTRY_ID);\n      sectionExists = section !== undefined;\n      webExists = webSection !== undefined;\n    }\n  } catch { return snapshot; }\n\n  try {\n    const resolved = await credentials.resolve(SEARCH_KEY_REF);\n    snapshot.credential = resolved && typeof resolved.value === 'string' ? resolved.value : null;\n  } catch { return snapshot; }\n\n  snapshot.section = sectionExists && section && typeof section === 'object' && !Array.isArray(section)\n    ? { ...section }\n    : (sectionExists ? {} : null);\n  snapshot.webSection = webExists && webSection && typeof webSection === 'object' && !Array.isArray(webSection)\n    ? { ...webSection }\n    : (webExists ? {} : null);\n  snapshot.summary = {\n    baseURL: typeof section?.baseURL === 'string' ? section.baseURL : '',\n    apiKeyRef: typeof section?.apiKeyEnv === 'string' ? section.apiKeyEnv : '',\n    hadLiteralKey: typeof section?.apiKey === 'string' && section.apiKey.length > 0,\n    provider: typeof webSection?.searchProvider === 'string' ? webSection.searchProvider : '',\n  };\n  // 分节不存在时没有“原配置”可恢复（一键接入本身也会因 namespace 未注册失败）。\n  snapshot.ok = sectionExists;\n  return snapshot;\n}\n\n/**\n * 把 dsh 的搜索配置恢复到一键接入前的快照。\n *\n * 只恢复 `web` / `web-search-deepseek` 两个分节和独立凭据引用；不碰\n * DEEPSEEK_API_KEY 或任何 WorkBuddy 客户端文件。任何一步失败都保留快照，\n * 让用户可以重试。\n *\n * @param {object} deps\n * @param {{ replace?: (ns: string, section: object) => Promise<void> }} deps.settings\n * @param {{ set?: (ref: string, value: string) => Promise<void>, unset?: (ref: string) => Promise<void> }} deps.credentials\n * @param {Awaited<ReturnType<typeof snapshotWorkBuddyWebSearch>>} deps.snapshot\n * @returns {Promise<{ reverted: boolean, summary: object }>}\n */\nexport async function restoreWorkBuddyWebSearch({ settings, credentials, snapshot } = {}) {\n  if (!snapshot?.ok) throw new Error('no restorable web search snapshot');\n  if (!settings || typeof settings.replace !== 'function') {\n    throw new Error('dsh settings service does not support restoring the previous section');\n  }\n\n  const errors = [];\n  if (snapshot.webSection !== null) {\n    try {\n      await settings.replace(WEB_ENTRY_ID, snapshot.webSection);\n    } catch (error) {\n      errors.push(`web: ${String(error?.message || error)}`);\n    }\n  }\n  try {\n    await settings.replace(WEB_SEARCH_ENTRY_ID, snapshot.section || {});\n  } catch (error) {\n    errors.push(`web-search-deepseek: ${String(error?.message || error)}`);\n  }\n\n  if (!credentials || typeof credentials.set !== 'function') {\n    errors.push('credentials service is unavailable');\n  } else {\n    try {\n      if (snapshot.credential) await credentials.set(SEARCH_KEY_REF, snapshot.credential);\n      else if (typeof credentials.unset === 'function') await credentials.unset(SEARCH_KEY_REF);\n      else errors.push('credentials service does not support unset');\n    } catch (error) {\n      errors.push(`credential: ${String(error?.message || error)}`);\n    }\n  }\n\n  if (errors.length) throw new Error(`restore incomplete: ${errors.join('; ')}`);\n  return { reverted: true, summary: snapshot.summary || {} };\n}\n\nconst normalizeBaseURL = (value) => (typeof value === 'string' ? value.replace(/\\/+$/, '') : '');\n\n/**\n * 这个地址是不是本地桥的搜索入口。\n *\n * 端口不参与判断：桥换端口（改配置、旧进程迁移）后仍应认成“我们自己接的”，\n * 由自动接入自愈，而不是把它误判成用户手工配置的第三方端点。\n */\nexport function isBridgeSearchEndpoint(value, expectedBaseURL) {\n  const actual = normalizeBaseURL(value);\n  const expected = normalizeBaseURL(expectedBaseURL);\n  if (!actual) return false;\n  if (expected && actual === expected) return true;\n  try {\n    const url = new URL(actual);\n    if (url.protocol !== 'http:' && url.protocol !== 'https:') return false;\n    if (!['127.0.0.1', 'localhost', '[::1]', '::1'].includes(url.hostname)) return false;\n    return url.pathname.replace(/\\/+$/, '') === '/v1';\n  } catch {\n    return false;\n  }\n}\n\n/**\n * 当前配置是否就是本插件写的那种形态。\n *\n * 只看“像不像”，不证明是谁写的：地址指向本机桥、没有字面 key、凭据引用是\n * 插件专用引用、provider 还是官方默认。自动接入用它区分「自己留下的配置」\n * 和「用户手写的配置」。\n */\nexport function looksLikeManagedSearchConfig({\n  section,\n  webSection,\n  expectedBaseURL,\n  searchKeyRef = SEARCH_KEY_REF,\n} = {}) {\n  if (!isBridgeSearchEndpoint(section?.baseURL, expectedBaseURL)) return false;\n  const apiKeyEnv = typeof section?.apiKeyEnv === 'string' ? section.apiKeyEnv : '';\n  if (apiKeyEnv !== '' && apiKeyEnv !== searchKeyRef) return false;\n  if (typeof section?.apiKey === 'string' && section.apiKey.length > 0) return false;\n  const provider = typeof webSection?.searchProvider === 'string' ? webSection.searchProvider : '';\n  return provider === '' || provider === 'deepseek-official';\n}\n\n/**\n * 用户是否**显式**选择了搜索后端。\n *\n * 入参必须是 `settings.describe()` 里的 user 层（只含用户改写过的字段），\n * 不能传合并后的解析值 —— 否则 bundle 默认值会被当成用户选择，自动接入永远\n * 不敢动。判据只取“换后端”的字段：baseURL / apiKey / apiKeyEnv / searchProvider；\n * maxUses 这类调参不算。\n */\nexport function hasExplicitSearchOverride({\n  section,\n  webSection,\n  expectedBaseURL,\n  searchKeyRef = SEARCH_KEY_REF,\n} = {}) {\n  const userSection = section && typeof section === 'object' ? section : {};\n  const userWeb = webSection && typeof webSection === 'object' ? webSection : {};\n  const baseURL = normalizeBaseURL(userSection.baseURL);\n  const managedEndpoint = baseURL !== '' && isBridgeSearchEndpoint(baseURL, expectedBaseURL);\n\n  if (baseURL !== '' && !managedEndpoint) return true;\n  if (typeof userSection.apiKey === 'string' && userSection.apiKey.length > 0) return true;\n  if (typeof userSection.apiKeyEnv === 'string' && userSection.apiKeyEnv !== ''\n    && userSection.apiKeyEnv !== searchKeyRef) return true;\n  const provider = typeof userWeb.searchProvider === 'string' ? userWeb.searchProvider : '';\n  if (provider !== '' && provider !== 'deepseek-official') return true;\n  // 显式选回官方 DeepSeek，但端点却不是桥：这是用户的决定，不能覆盖。\n  if (provider === 'deepseek-official' && !managedEndpoint) return true;\n  return false;\n}\n\n/**\n * 启动时要不要自动接入。\n *\n * @returns {{ action: 'configure' | 'skip' | 'wait', reason: string }}\n *   - configure：可以写配置（auto = 首次接入，heal = 修复令牌/端口漂移）\n *   - skip：用户显式配置、已接入、或宿主没有搜索 provider\n *   - wait：桥/服务还没就绪，稍后再试\n */\nexport function decideWebSearchAutoSetup({\n  enabled = true,\n  status,\n  explicitOverride = false,\n  managed = false,\n  bridgeState = 'stopped',\n} = {}) {\n  if (!enabled) return { action: 'skip', reason: 'disabled' };\n  if (!status || status.available !== true) return { action: 'wait', reason: 'unavailable' };\n  if (status.reason === 'namespace-missing') return { action: 'skip', reason: 'unavailable' };\n  // 读配置本身失败时绝不能“当作没配过”然后去写，先等下一轮。\n  if (status.reason === 'error') return { action: 'wait', reason: 'settings' };\n  if (status.configured === true && status.tokenMatches !== false) {\n    return { action: 'skip', reason: 'configured' };\n  }\n  if (explicitOverride && !managed) return { action: 'skip', reason: 'explicit' };\n  if (bridgeState !== 'running') return { action: 'wait', reason: 'bridge' };\n  return { action: 'configure', reason: managed ? 'heal' : 'auto' };\n}\n\n/**\n * 读搜索配置的**生效值 + 用户层**。\n *\n * 这台 dsh 的 `settings` 服务只有 `describe()/update()/replace()`，**没有\n * `get(ns)`**；旧代码用 `settings.get` 判断，结果把真实存在的搜索配置误判成\n * “不可用”，自动接入也被跳过（issue #7 里入口看起来消失的根因）。\n *\n * 读取顺序：\n *   1. 有 `describe()` 就以它为准（`value` = 生效值，`user` = 用户改写层）；\n *   2. 兼容只有 `get(ns)` 的旧宿主；\n *   3. 两者都没有 → 不可用。\n *\n * 某些测试桩的 `describe()` 只给 `user` 不给 `value`，此时用 `get` 补生效值；\n * 两者都没有时用空对象，交给调用方按“分节存在但为空”处理。\n *\n * @returns {{\n *   available: boolean, error: boolean, section: object | undefined,\n *   webSection: object | undefined, searchUser: object | null,\n *   webUser: object | null, hasWeb: boolean, source: string\n * }}\n */\nexport function readWebSearchConfig(settings) {\n  const empty = {\n    available: false,\n    error: false,\n    section: undefined,\n    webSection: undefined,\n    searchUser: null,\n    webUser: null,\n    hasWeb: false,\n    source: 'none',\n  };\n  if (!settings) return empty;\n\n  let descriptors = null;\n  if (typeof settings.describe === 'function') {\n    try {\n      const list = settings.describe();\n      if (Array.isArray(list)) descriptors = list;\n    } catch {\n      return { ...empty, error: true, source: 'describe' };\n    }\n  }\n\n  const read = (ns) => {\n    let fallback;\n    const getValue = () => {\n      if (fallback !== undefined) return fallback;\n      fallback = null;\n      if (typeof settings.get === 'function') {\n        try { fallback = settings.get(ns); } catch { fallback = null; }\n      }\n      return fallback;\n    };\n\n    if (descriptors) {\n      const descriptor = descriptors.find((item) => item && item.ns === ns);\n      if (!descriptor) return { exists: false, value: undefined, user: {} };\n      const value = descriptor.value && typeof descriptor.value === 'object'\n        ? descriptor.value\n        : (getValue() || {});\n      return {\n        exists: true,\n        value,\n        user: descriptor.user && typeof descriptor.user === 'object' ? { ...descriptor.user } : {},\n      };\n    }\n    if (typeof settings.get === 'function') {\n      const value = getValue();\n      return { exists: value !== undefined && value !== null, value, user: null };\n    }\n    return { exists: false, value: undefined, user: null };\n  };\n\n  const search = read(WEB_SEARCH_ENTRY_ID);\n  const web = read(WEB_ENTRY_ID);\n  return {\n    available: search.exists,\n    error: false,\n    section: search.exists ? search.value : undefined,\n    webSection: web.exists ? web.value : undefined,\n    searchUser: search.user,\n    webUser: web.user,\n    hasWeb: web.exists,\n    source: descriptors ? 'describe' : (typeof settings.get === 'function' ? 'get' : 'none'),\n  };\n}\n\n/**\n * 读 describe() 的 user 层（只有用户改写过的字段）。\n * 保留这个轻量入口给恢复/退出自动接入使用；需要生效值时用\n * {@link readWebSearchConfig}（一次 describe 同时拿两份数据）。\n *\n * @returns {{ available: boolean, search: object | null, web: object | null, hasWeb: boolean }}\n */\nexport function readWebSearchUserLayers(settings) {\n  const config = readWebSearchConfig(settings);\n  return {\n    available: config.available,\n    search: config.searchUser,\n    web: config.webUser,\n    hasWeb: config.hasWeb,\n  };\n}\n\n/**\n * 没有内存快照时的回滚：只摘掉本插件写进去的字段。\n *\n * 用在「自动接入后重启了 dsh」：这时原配置快照已经随内存消失，但我们仍能\n * 认出自己的指纹（桥地址 + 插件专用凭据引用），把它们删掉就回到 bundle 默认。\n * 不会碰用户的其它搜索字段（maxUses 等）。\n */\nexport async function resetWorkBuddyWebSearchOverrides({\n  settings,\n  credentials,\n  expectedBaseURL,\n  searchKeyRef = SEARCH_KEY_REF,\n} = {}) {\n  if (!settings || typeof settings.describe !== 'function' || typeof settings.replace !== 'function') {\n    throw new Error('dsh settings service does not support inspecting or restoring search settings');\n  }\n  const descriptors = settings.describe();\n  const list = Array.isArray(descriptors) ? descriptors : [];\n  const searchDesc = list.find((item) => item && item.ns === WEB_SEARCH_ENTRY_ID);\n  if (!searchDesc) throw new Error('dsh web search section is not configurable');\n\n  const section = searchDesc.user && typeof searchDesc.user === 'object' ? { ...searchDesc.user } : {};\n  const removed = [];\n  if (isBridgeSearchEndpoint(section.baseURL, expectedBaseURL)) {\n    delete section.baseURL;\n    removed.push('baseURL');\n  }\n  if (typeof section.apiKeyEnv === 'string' && section.apiKeyEnv === searchKeyRef) {\n    delete section.apiKeyEnv;\n    removed.push('apiKeyEnv');\n  }\n  if (section.apiKey === '') {\n    delete section.apiKey;\n    removed.push('apiKey');\n  }\n  if (!removed.length) throw new Error('current web search configuration was not installed by WorkBuddy');\n\n  await settings.replace(WEB_SEARCH_ENTRY_ID, section);\n\n  const webDesc = list.find((item) => item && item.ns === WEB_ENTRY_ID);\n  if (webDesc) {\n    const webSection = webDesc.user && typeof webDesc.user === 'object' ? { ...webDesc.user } : {};\n    webSection.searchProvider = 'deepseek-official';\n    await settings.replace(WEB_ENTRY_ID, webSection);\n  } else {\n    // 没有 web 分节时，用显式的默认凭据引用留下“用户选择”标记，\n    // 避免下次启动又自动接回来。\n    section.apiKeyEnv = 'DEEPSEEK_API_KEY';\n    await settings.replace(WEB_SEARCH_ENTRY_ID, section);\n  }\n\n  if (credentials && typeof credentials.unset === 'function') {\n    try { await credentials.unset(searchKeyRef); } catch { /* 凭据本来就不存在时忽略 */ }\n  }\n  return { reverted: true, removed, summary: { baseURL: '', apiKeyRef: '' } };\n}\n\n/**\n * 回滚之后留下“不要再自动接入”的显式标记。\n *\n * 优先写 `web.searchProvider = deepseek-official`（dsh 认识的原生字段）；\n * 没有 web 分节时写 `apiKeyEnv = DEEPSEEK_API_KEY`。两者都与默认值等价，\n * 但会进入 user 层，自动接入据此尊重用户选择。\n *\n * @returns {{ marked: boolean, reason: string }}\n */\nexport async function markWorkBuddyWebSearchOptOut({\n  settings,\n  searchKeyRef = SEARCH_KEY_REF,\n} = {}) {\n  if (!settings || typeof settings.describe !== 'function' || typeof settings.replace !== 'function') {\n    return { marked: false, reason: 'settings-unavailable' };\n  }\n  const layers = readWebSearchUserLayers(settings);\n  if (!layers.available) return { marked: false, reason: 'section-missing' };\n  const search = layers.search || {};\n  const web = layers.web || {};\n  const explicit = hasExplicitSearchOverride({\n    section: search,\n    webSection: web,\n    expectedBaseURL: '',\n    searchKeyRef,\n  });\n  if (explicit) return { marked: false, reason: 'already-explicit' };\n\n  if (layers.hasWeb) {\n    await settings.replace(WEB_ENTRY_ID, { ...web, searchProvider: 'deepseek-official' });\n    return { marked: true, reason: 'provider' };\n  }\n  await settings.replace(WEB_SEARCH_ENTRY_ID, { ...search, apiKeyEnv: 'DEEPSEEK_API_KEY' });\n  return { marked: true, reason: 'key-ref' };\n}\n\n/**\n * 判断 dsh 的网页搜索当前是否真的指向本地桥。\n *\n * 只做配置层判断（不发起搜索）：接口地址、凭据引用、provider 选择三者都对了\n * 才算“已接入”。凭据是否真的存在由调用方查 credentials 后传入。\n *\n * @param {object} deps\n * @param {object | undefined} deps.section `web-search-deepseek` 的已解析分节\n * @param {object | undefined} deps.webSection `web` 分节的已解析值（rc.6 不存在）\n * @param {string} deps.expectedBaseURL 本地桥地址，例如 http://127.0.0.1:8790/v1\n * @param {boolean} deps.keyConfigured 凭据引用（或字面 apiKey）是否已配置\n * @returns {{ configured: boolean, pointsToBridge: boolean, providerSelected: boolean, provider: string, baseURL: string, apiKeyRef: string, reason: string }}\n */\nexport function deriveWebSearchStatus({ section, webSection, expectedBaseURL, keyConfigured = false }) {\n  const baseURL = normalizeBaseURL(section?.baseURL);\n  const apiKeyRef = typeof section?.apiKeyEnv === 'string' ? section.apiKeyEnv : '';\n  const provider = typeof webSection?.searchProvider === 'string' ? webSection.searchProvider : '';\n  const pointsToBridge = baseURL !== '' && baseURL === normalizeBaseURL(expectedBaseURL);\n  // rc.6 没有 `web` 分节；没有显式选择时沿用 bundle patch 的 deepseek-official。\n  const providerSelected = provider === '' || provider === 'deepseek-official';\n  const configured = pointsToBridge && keyConfigured === true && providerSelected;\n  const reason = configured\n    ? ''\n    : !pointsToBridge ? 'endpoint'\n      : !keyConfigured ? 'key'\n        : 'provider';\n  return { configured, pointsToBridge, providerSelected, provider, baseURL, apiKeyRef, reason };\n}\n\n/**\n * 把配置状态、桥状态、凭据是否匹配和最近一次自检合并成面板可用的“现在能不能用”。\n *\n * `configured` 只代表 settings 写对了；桥没跑、令牌被轮换时它仍然为真。\n * 面板必须用这里的 `ready`，否则会出现“绿色但搜索必失败”。\n *\n * @param {object} deps\n * @param {ReturnType<typeof deriveWebSearchStatus>} deps.status\n * @param {string} deps.bridgeState supervisor.probe() 的状态\n * @param {boolean | null} deps.tokenMatches 凭据值是否等于当前桥令牌；null = 无法比对\n * @param {{ at?: number, verified?: boolean | null, sourceCount?: number, error?: string, baseURL?: string } | null} [deps.verification]\n * @param {string} [deps.expectedBaseURL]\n * @returns {{ ready: boolean, reason: string, bridgeState: string, tokenMatches: boolean | null, lastVerifiedAt: string, lastVerifySourceCount: number | null, lastVerifyError: string, lastVerifyStale: boolean, lastVerifyFailed: boolean, lastVerifyVerified: boolean | null }}\n */\nexport function deriveWebSearchReadiness({\n  status,\n  bridgeState,\n  tokenMatches = null,\n  verification = null,\n  expectedBaseURL = '',\n} = {}) {\n  const configReady = status?.configured === true;\n  const bridgeReady = bridgeState === 'running';\n  const tokenReady = tokenMatches !== false;\n  const ready = configReady && bridgeReady && tokenReady;\n\n  let reason = '';\n  if (!configReady) reason = typeof status?.reason === 'string' && status.reason ? status.reason : 'config';\n  else if (!bridgeReady) {\n    // 桥进程在、但登录/令牌/端口有问题：不要笼统说“桥未运行”，那会让用户\n    // 去启动一个其实已经在跑的桥。\n    if (bridgeState === 'degraded' || bridgeState === 'unauthenticated') reason = 'bridge-auth';\n    else if (bridgeState === 'unauthorized' || bridgeState === 'foreign') reason = 'bridge-conflict';\n    else reason = 'bridge';\n  } else if (tokenMatches === false) reason = 'token';\n\n  const hasVerification = Boolean(verification && verification.at);\n  const stale = hasVerification && (\n    tokenMatches === false\n    || (typeof verification.baseURL === 'string'\n      && verification.baseURL !== ''\n      && typeof expectedBaseURL === 'string'\n      && expectedBaseURL !== ''\n      && verification.baseURL.replace(/\\/+$/, '') !== expectedBaseURL.replace(/\\/+$/, ''))\n  );\n  return {\n    ready,\n    reason,\n    bridgeState: typeof bridgeState === 'string' ? bridgeState : '',\n    tokenMatches: tokenMatches === true || tokenMatches === false ? tokenMatches : null,\n    lastVerifiedAt: hasVerification ? new Date(verification.at).toISOString() : '',\n    lastVerifySourceCount: hasVerification && Number.isFinite(verification.sourceCount)\n      ? verification.sourceCount\n      : null,\n    lastVerifyError: hasVerification && typeof verification.error === 'string' ? verification.error : '',\n    lastVerifyStale: stale,\n    lastVerifyFailed: hasVerification && verification.verified === false && !stale,\n    lastVerifyVerified: hasVerification && (verification.verified === true || verification.verified === false)\n      ? verification.verified\n      : null,\n  };\n}\n\n/**\n * 用 dsh 自己的 web 服务跑一次真实搜索，证明「配置 + 凭据 + 桥」整条链路可用。\n *\n * 这比只回显 baseURL 更可靠：令牌不对、桥没起、provider 没热更，都会在这里\n * 以失败出现，而不是等用户下一次搜索才发现。\n *\n * @param {object} deps\n * @param {{ search: (request: object, signal?: AbortSignal) => Promise<object> } | undefined} deps.web\n * @param {string} [deps.query]\n * @param {number} [deps.maxResults]\n * @param {number} [deps.timeoutMs]\n * @returns {Promise<{ verified: boolean | null, sourceCount?: number, verifyError?: string }>}\n *   `verified: null` 表示当前 dsh 没有 web 服务，跳过自检（不是失败）。\n */\nexport async function verifyWorkBuddyWebSearch({\n  web,\n  query = 'WorkBuddy',\n  maxResults = 1,\n  timeoutMs = 20000,\n} = {}) {\n  if (!web || typeof web.search !== 'function') return { verified: null };\n\n  const controller = new AbortController();\n  let timedOut = false;\n  const timer = timeoutMs > 0\n    ? setTimeout(() => {\n      timedOut = true;\n      controller.abort(new Error('web search self-test timed out'));\n    }, timeoutMs)\n    : null;\n  try {\n    const result = await web.search({ query, maxResults }, controller.signal);\n    const sourceCount = Array.isArray(result?.sources) ? result.sources.length : 0;\n    // 自检请求的是固定词；0 来源说明链路有问题（桥回空、provider 没接上），\n    // 不能把“没抛错”当成成功。\n    if (sourceCount === 0) {\n      return { verified: false, sourceCount: 0, verifyError: 'self-test returned 0 sources' };\n    }\n    return { verified: true, sourceCount };\n  } catch (error) {\n    return {\n      verified: false,\n      verifyError: timedOut\n        ? `self-test timed out after ${timeoutMs}ms`\n        : String(error?.message || error),\n    };\n  } finally {\n    if (timer) clearTimeout(timer);\n  }\n}\n"
    },
