available on Windows');\n  const script = 'Add-Type -AssemblyName System.Security; '\n    + '$in=[Console]::In.ReadToEnd().Trim(); $b=[Convert]::FromBase64String($in); '\n    + `$p=[Security.Cryptography.ProtectedData]::${verb}($b,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser); `\n    + '[Console]::Out.Write([Convert]::ToBase64String($p))';\n  const res = await runChild(wbPowershellPath(), ['-NoProfile', '-NonInteractive', '-Command', script], {\n    input: inputBase64,\n    stdio: ['pipe', 'pipe', 'pipe'],\n    timeout: 20000,\n    maxBuffer: 1024 * 1024,\n  });\n  if (res.error) throw new Error(`DPAPI ${verb} failed: ${res.error.message}`);\n  if (res.code !== 0) {\n    throw new Error(`DPAPI ${verb} failed: exit ${res.code} ${String(res.stderr || '').trim().slice(0, 200)}`);\n  }\n  const out = String(res.stdout || '').trim();\n  if (!out) throw new Error(`DPAPI ${verb} returned empty output`);\n  return out;\n}\n\nconst dpapiProtect = (buffer) => dpapiCall('Protect', buffer.toString('base64'));\nconst dpapiUnprotect = async (base64) => Buffer.from(await dpapiCall('Unprotect', base64), 'base64');\n\n/** 解析 file 模式密钥：hex / base64(32B) 原样用，其余按口令经 scrypt 派生。 */\nfunction parseCredentialKey(raw) {\n  const text = String(raw || '').trim();\n  if (!text) return null;\n  if (/^[0-9a-f]{64}$/i.test(text)) return Buffer.from(text, 'hex');\n  try {\n    const decoded = Buffer.from(text, 'base64');\n    if (decoded.length === 32) return decoded;\n  } catch { /* 不是 base64：按口令处理 */ }\n  return scryptSync(text, 'workbuddy-credential-store-v1', 32);\n}\n\n/**\n * 凭据目录里有没有已加密的凭据（用来判断「密钥丢了」是不是致命）。\n * 只看文件名，不解密；读不到目录按\"没有\"处理（首次运行）。\n */\nfunction hasEncryptedCredentials() {\n  try { return readdirSync(CREDENTIAL_DIR).some((f) => f.endsWith('.cred')); }\n  catch { return false; }\n}\n\n/**\n * 排它地写密钥文件（`wx`）。多个进程同时首次启动时只有一个能创建成功，\n * 输家回读赢家写下的值 —— 否则两个进程各生成一把密钥，先写入的凭据\n * 从此再也解不开（`writeFileAtomic` 是覆盖写，挡不住这种竞争）。\n */\nfunction writeCredentialKeyExclusive(file, content) {\n  try {\n    writeFileSync(file, content, { mode: 0o600, flag: 'wx' });\n    return { created: true };\n  } catch (error) {\n    if (error?.code === 'EEXIST') return { created: false };\n    throw error;\n  }\n}\n\n/** 取/建字段密钥；失败**不静默明文**，由调用方回退到 memory。 */\nasync function loadOrCreateCredentialKey() {\n  /*\n   * 环境变量密钥是常量来源，可以安全短路。**其余来源不能**：早先这里对所有\n   * 来源都 `if (credentialKey) return credentialKey`，于是下面的 stat 比对\n   * 永远走不到 —— store.key 轮换后桥会一直用旧密钥，新写入的凭据下次启动\n   * 就解不开了。\n   */\n  if (credentialKey && credentialKeySource === 'env') return credentialKey;\n  if (credentialKeyPending) return credentialKeyPending;\n  credentialKeyPending = (async () => {\n    ensureCredentialDir();\n    const file = credentialKeyFile();\n    /*\n     * file 模式：Windows 之外的默认。优先用环境变量密钥（推荐容器部署：\n     * 密钥不进持久卷，换机器也不会跟着被拷走），否则生成 0600 的 store.key。\n     */\n    if (CREDENTIAL_STORE_MODE === 'file') {\n      if (CREDENTIAL_KEY_ENV) {\n        const fromEnv = parseCredentialKey(CREDENTIAL_KEY_ENV);\n        if (!fromEnv || fromEnv.length !== 32) throw new Error('WORKBUDDY_CREDENTIAL_KEY is not a valid key');\n        credentialKey = fromEnv;\n        credentialKeySource = 'env';\n        credentialKeyPrint = 'env';\n        return credentialKey;\n      }\n      if (existsSync(file)) {\n        const st = statSync(file);\n        const print = `${st.mtimeMs}:${st.size}`;\n        if (credentialKey && credentialKeyPrint === print) return credentialKey;\n        let blob;\n        try { blob = readFileSync(file, 'utf8').trim(); }\n        catch (e) { throw new Error(`cannot read credential key: ${e.message}`, { cause: e }); }\n        const key = parseCredentialKey(blob);\n        if (!key || key.length !== 32) throw new Error('credential key file is malformed');\n        credentialKey = key;\n        credentialKeySource = 'file';\n        credentialKeyPrint = print;\n        return key;\n      }\n      /*\n       * store.key 不见了、但目录里还有 `.cred`：**绝不能**静默生成新密钥。\n       * 新密钥能正常工作，旧凭